// Interview questions + answers per Lead Essentials checklist topic.
// Keyed by the exact topic string used in checklistTopics.js (section id: 'essentials').
// Each entry is { q, a } — q is the question, a is a senior-level answer covering the key points.
export const essentialsQuestions = {
  // Web / React Performance
  'Core Web Vitals: LCP, INP, CLS (and FCP, TTFB)': [
    { q: 'What does LCP measure and what are common causes of a poor LCP score?', a: 'LCP (Largest Contentful Paint) measures how long it takes for the largest visible content element (usually a hero image, video, or large text block) to render on screen. Common causes of poor LCP: slow server response times (high TTFB), render-blocking CSS/JS, unoptimized/oversized images, client-side rendering that delays content until JS loads and executes, and lack of resource prioritization for the LCP element itself.' },
    { q: 'How is INP different from FID, and why did Google replace FID with INP?', a: 'FID (First Input Delay) only measured the delay before the browser could begin processing the very first user interaction. INP (Interaction to Next Paint) measures the full latency of every interaction throughout the page\'s lifetime, from input to the next visual update, taking the worst (or near-worst) one — a much more comprehensive signal of overall responsiveness, since a page could have a great FID but still feel janky on later interactions, which FID simply never captured.' },
    { q: 'What causes Cumulative Layout Shift and how do you prevent it?', a: 'CLS is caused by visible elements shifting position unexpectedly — images/embeds without reserved dimensions, web fonts causing a FOUT/FOIT reflow, dynamically injected content (ads, banners) pushing existing content down, and animations that affect layout properties instead of transform/opacity. Prevention: always specify width/height (or aspect-ratio) on images/embeds, reserve space for dynamic content upfront, use font-display strategies that minimize layout shift, and animate only compositor-friendly properties.' },
    { q: 'How do TTFB and FCP relate to each other in the critical rendering path?', a: 'TTFB (Time to First Byte) measures how long until the browser receives the first byte of the server\'s response — it\'s the earliest possible point anything can start happening. FCP (First Contentful Paint) measures when the first actual content (text, image) appears on screen, which necessarily happens after TTFB, since the browser needs the response before it can parse and render anything — a slow TTFB puts a hard floor under how fast FCP can possibly be.' },
  ],
  'Setting and enforcing performance budgets': [
    { q: 'What is a performance budget and how do you enforce it in CI?', a: 'A performance budget is a set of quantitative limits (bundle size, LCP threshold, number of requests) that a build/deployment must not exceed. You enforce it in CI by running automated checks (Lighthouse CI, bundlesize, size-limit) on every PR/build that fail the pipeline if a budget is exceeded, catching regressions before they reach production rather than relying on manual review or post-deploy monitoring alone.' },
    { q: 'Which metrics would you put in a budget for a React app, and at what thresholds?', a: 'Common choices: total JS bundle size (e.g. under 200-300KB gzipped for the initial route), LCP (under 2.5s), CLS (under 0.1), INP (under 200ms), and number of third-party scripts — exact thresholds depend on the target audience/device profile (a budget for a mostly-mobile, emerging-market audience would be stricter than one for a desktop-heavy enterprise app).' },
  ],
  'Critical rendering path and reducing reflow/repaint': [
    { q: 'What is the critical rendering path and which steps can you optimize?', a: 'The critical rendering path is the sequence of steps the browser takes to convert HTML/CSS/JS into pixels on screen: parse HTML into the DOM, parse CSS into the CSSOM, combine them into the render tree, compute layout, and paint. You optimize it by minimizing render-blocking resources (deferring non-critical CSS/JS), inlining critical CSS, reducing DOM complexity, and prioritizing above-the-fold content delivery.' },
    { q: 'What is the difference between a reflow and a repaint — which is more expensive?', a: 'A reflow (layout) recalculates the geometry (position/size) of elements, potentially cascading to affect many other elements in the tree. A repaint only redraws pixels for visual changes that don\'t affect layout (color, background). Reflow is more expensive because it can trigger a full cascade of layout recalculation across the affected subtree (or the whole page), whereas a repaint is typically more localized and doesn\'t require recomputing geometry.' },
    { q: 'How does CSS `will-change` or `transform` prevent reflows during animations?', a: 'Animating `transform` and `opacity` can be handled entirely by the compositor thread, skipping layout and paint altogether for each frame — the browser just recombines already-rasterized layers with a new transform matrix. `will-change` hints to the browser to promote an element to its own compositor layer ahead of time, avoiding the cost of layer creation happening mid-animation, though overusing it wastes memory by creating too many layers.' },
  ],
  'Bundle analysis and reducing bundle size': [
    { q: 'How would you analyze what is contributing most to a large JS bundle?', a: 'Use a bundle analyzer tool (webpack-bundle-analyzer, source-map-explorer, or Vite\'s rollup-plugin-visualizer) to generate a treemap visualization showing exactly which packages/modules contribute how much to the final bundle size, making it easy to spot unexpectedly large dependencies or duplicated packages.' },
    { q: 'What are the most common causes of bloated JavaScript bundles in React apps?', a: 'Importing entire libraries instead of specific functions (moment.js, full lodash instead of lodash-es individual imports), duplicate dependency versions from mismatched package resolutions, unnecessary polyfills for already-supported features, not code-splitting rarely-used routes/features, and including large icon libraries or UI kits wholesale instead of tree-shaken/individual imports.' },
  ],
  'Code splitting (route-based and component-based)': [
    { q: 'What is the difference between route-based and component-based code splitting?', a: 'Route-based splitting divides your bundle along route boundaries, so each page/route only loads its own JS on navigation, rather than the entire app upfront. Component-based splitting is more granular — lazy-loading individual heavy components (a rich text editor, a chart library, a modal) only when they\'re actually needed within a page, regardless of route boundaries.' },
    { q: "How do you lazily load a heavy component only when it's first needed?", a: 'Use React.lazy with dynamic import: `const Chart = React.lazy(() => import("./Chart"))`, wrapped in a Suspense boundary with a fallback — the component\'s code becomes a separate chunk only downloaded the first time it\'s actually rendered, rather than being part of the initial bundle.' },
  ],
  'Tree shaking and dead-code elimination': [
    { q: 'What is tree shaking and what conditions must be met for it to work?', a: 'Tree shaking is a bundler optimization that removes unused exports from the final bundle by statically analyzing the module dependency graph. It requires ES module syntax (static import/export, not CommonJS\'s dynamic require), since the bundler needs to determine at build time — without executing any code — exactly which exports are actually used anywhere in the app.' },
    { q: 'Why does importing from a barrel file sometimes defeat tree shaking?', a: 'A barrel file (an index.js re-exporting everything from a package) can cause the bundler to include the entire barrel\'s module graph even if you only imported one specific named export, especially if any of the re-exported modules have side effects at the top level that the bundler can\'t safely prove are removable — this is why some libraries recommend deep/direct imports (`lodash/debounce`) over importing from the package root.' },
  ],
  'Lazy loading components, routes, and images': [
    { q: 'How do you lazy-load an image below the fold without a third-party library?', a: 'Use the native `loading="lazy"` attribute on an `<img>` tag — the browser automatically defers loading that image until it\'s about to scroll into the viewport, with zero JavaScript required; for more control (custom thresholds, fade-in effects), you can pair it with IntersectionObserver instead.' },
    { q: 'How does Intersection Observer help with lazy loading?', a: 'IntersectionObserver lets you asynchronously observe when an element crosses into (or near) the viewport, without expensive synchronous scroll-event-driven position calculations — you attach it to placeholder elements, and when the callback reports intersection, you swap in the real image/content, achieving efficient, non-blocking lazy loading.' },
  ],
  'React.memo / useMemo / useCallback — and when NOT to use them': [
    { q: 'When does React.memo actually prevent a re-render, and when does it fail?', a: 'React.memo prevents a re-render only when all props are shallowly equal to the previous render\'s props. It fails whenever any prop is a new reference each render (an inline object/array/function literal), since shallow comparison treats a new reference as "changed" even if the underlying value is logically identical — the parent needs to memoize such props (with useMemo/useCallback) for React.memo\'s comparison to actually succeed.' },
    { q: 'What is the cost of useMemo/useCallback themselves, and when do they cost more than they save?', a: 'Both have their own overhead — comparing the dependency array and storing the cached value/function consumes memory and a small amount of computation on every render. For cheap computations or components not wrapped in React.memo (so the memoization has no downstream effect), this overhead can exceed the cost of just recomputing the value/function directly, making the memoization pure waste.' },
    { q: 'Give an example of over-memoization that makes code worse without helping performance.', a: 'Wrapping a simple string concatenation in useMemo (`useMemo(() => firstName + " " + lastName, [firstName, lastName])`), or useCallback-wrapping a handler passed only to a plain, non-memoized `<button>` — in both cases the memoization adds code complexity and its own small runtime cost while providing zero actual re-render-prevention benefit, since there\'s nothing downstream capable of taking advantage of the referential stability.' },
  ],
  'Fixing unnecessary re-renders (state colocation, context splitting)': [
    { q: 'How does colocating state prevent unnecessary re-renders of parent components?', a: 'Moving state to live in the smallest, most local component that actually needs it (rather than lifting it higher than necessary) means only that local component (and its own children) re-renders when the state changes, instead of a broader parent re-rendering and cascading down to unrelated sibling subtrees that don\'t depend on that state at all.' },
    { q: 'How does splitting a context into read and write contexts reduce consumer re-renders?', a: 'If dispatch (from useReducer) is provided through the same context as state, every state change re-renders even components that only need dispatch (which never actually changes reference). Splitting into a separate StateContext and DispatchContext means components that only call actions never re-render due to state updates, since they\'re not subscribed to the state context at all.' },
  ],
  'List virtualization / windowing for large lists': [
    { q: 'What is list virtualization and how does it improve rendering for 10,000-item lists?', a: 'Virtualization renders only the list items currently visible (plus a small buffer) in the viewport, rather than all 10,000 items simultaneously — dramatically reducing the number of DOM nodes created/managed/painted, keeping render and scroll performance roughly constant regardless of total list length instead of degrading linearly with item count.' },
    { q: 'What are the trade-offs of virtualization (e.g. variable-height items, accessibility)?', a: 'Variable-height items are harder to virtualize efficiently (requiring measurement or estimation strategies that add complexity and can cause scroll-position jumpiness). Accessibility can suffer since screen readers may not correctly announce list length/position when most items aren\'t actually in the DOM at any given time, requiring extra ARIA attributes (aria-setsize, aria-posinset) to compensate.' },
  ],
  'Image optimization (WebP/AVIF, responsive images, CDN, lazy)': [
    { q: 'How do srcset and sizes attributes work for responsive images?', a: 'srcset provides a list of image candidates at different resolutions/widths, and sizes tells the browser how much viewport width the image will occupy at different breakpoints — the browser combines this information with the actual device\'s viewport size and pixel density to automatically pick and download the most appropriately-sized image, avoiding wasted bandwidth on oversized images for small screens.' },
    { q: 'What is the difference between WebP and AVIF, and which should you prefer?', a: 'AVIF generally achieves better compression (smaller file sizes for equivalent visual quality) than WebP, but has slightly less universal browser support and can be slower to encode. WebP has near-universal modern browser support and good compression. A common pattern is serving AVIF with a WebP fallback (and a JPEG/PNG fallback further down) via the `<picture>` element, letting the browser pick the best format it supports.' },
    { q: 'How does serving images from a CDN with a CDN cache improve performance?', a: 'A CDN caches images at edge locations geographically close to users, reducing latency compared to fetching from a single origin server, and offloads the repeated-request load from your origin entirely — combined with long cache lifetimes (since image assets are often immutable/content-hashed), this means most image requests are served almost instantly from a nearby cache rather than round-tripping to the origin.' },
  ],
  'Resource hints: preload, prefetch, preconnect, dns-prefetch': [
    { q: 'What is the difference between preload and prefetch?', a: 'preload tells the browser to fetch a resource with high priority because it\'s needed for the CURRENT page/navigation (e.g. a critical font or hero image) — it should be used sparingly for things genuinely needed immediately. prefetch tells the browser to fetch a resource at low priority because it MIGHT be needed for a future navigation (e.g. the next likely route), so it doesn\'t compete with the current page\'s critical resources.' },
    { q: 'When would you use preconnect vs dns-prefetch?', a: 'dns-prefetch only resolves the DNS lookup for a domain ahead of time — a lightweight hint useful for many third-party domains you might use. preconnect goes further, establishing the full connection (DNS + TCP handshake + TLS negotiation) ahead of time — more expensive per-connection, so reserve it for a small number of critical, definitely-needed cross-origin connections (like your main API or font CDN) rather than every third-party domain on the page.' },
    { q: 'What is the risk of overusing preload?', a: 'Preloading too many resources competes for the same limited bandwidth/connection priority as the resources actually needed to render the current page, potentially delaying the true critical path resources and paradoxically hurting LCP/FCP — preload should be reserved for a small number of genuinely critical, provably-needed resources, not applied broadly.' },
  ],
  'HTTP caching, CDN caching, and cache busting': [
    { q: 'What is the difference between Cache-Control: max-age and s-maxage?', a: 'max-age applies to both browser (private) caches and shared/CDN caches — it\'s the general freshness lifetime. s-maxage specifically overrides max-age for shared caches (CDNs, proxies) only, letting you set a different (often longer) cache lifetime for CDN-level caching than what individual browsers should cache for, useful for content that a CDN can serve broadly but that a browser shouldn\'t necessarily hold onto as long.' },
    { q: 'How does content hashing enable aggressive long-term caching for JS assets?', a: 'Build tools embed a hash of the file\'s content into its filename (e.g. `app.a3f8e1.js`) — since the filename itself changes whenever the content changes, you can safely set an extremely long cache lifetime (a year or more, immutable) on these hashed assets, because any actual content change automatically produces a new, different URL that bypasses the old cached version entirely, rather than needing cache invalidation.' },
    { q: 'What does a CDN cache invalidation strategy look like for a React SPA?', a: 'Typically, the content-hashed JS/CSS bundle files are cached essentially forever (immutable), while the single entry HTML file (which references the current hashed bundle names) is cached with a short lifetime or set to always revalidate — deploying a new version just means uploading new hashed assets and updating the HTML, and since the HTML re-fetches quickly, users pick up the new bundle references almost immediately without needing to explicitly purge the CDN cache for the JS/CSS files themselves.' },
  ],
  'Debounce / throttle for expensive handlers': [
    { q: 'What is the difference between debounce and throttle, and when do you use each?', a: 'Debounce delays execution until activity has paused for a specified duration — useful for search-as-you-type inputs, where you want to wait until the user stops typing before firing an API call. Throttle guarantees execution at most once per fixed interval during continuous activity — useful for scroll or resize handlers, where you want periodic updates throughout the ongoing interaction, not just once at the end.' },
    { q: 'Implement a debounce function. What edge cases should it handle?', a: '`function debounce(fn, delay) { let timer; return (...args) => { clearTimeout(timer); timer = setTimeout(() => fn(...args), delay); }; }` — edge cases to consider: providing a way to cancel a pending call (e.g. on component unmount), preserving `this` context if used as a method, and deciding whether you need a "leading edge" variant (fires immediately on the first call, then debounces subsequent calls) for cases where an instant initial response matters.' },
  ],
  'SSR / streaming / RSC to improve TTFB and TTI': [
    { q: 'How does SSR improve Time to First Byte compared to a pure client-side SPA?', a: 'Actually, SSR typically has a *higher* TTFB than a static/cached SPA shell, since the server must render the full page before responding — but SSR dramatically improves the more meaningful metrics of FCP/LCP, since the browser receives fully-formed, visible HTML immediately rather than an empty shell that only becomes visible after JS downloads, parses, and renders client-side.' },
    { q: 'How does streaming SSR improve the perceived load time over buffered SSR?', a: 'Buffered SSR waits for the entire page (including all data-fetching) to finish rendering server-side before sending any response at all. Streaming SSR sends HTML progressively as pieces become ready — fast, non-data-dependent parts of the page arrive and render immediately, while slower parts (wrapped in Suspense) stream in later — improving perceived performance since users see meaningful content much sooner rather than waiting for the single slowest piece of data.' },
    { q: 'How do React Server Components reduce Time to Interactive by reducing client JS?', a: 'Server Components render entirely on the server and ship only their output (not their implementation code or dependencies) to the client — any component/library that doesn\'t need client-side interactivity contributes zero bytes to the client JS bundle, meaning less JS to download, parse, and execute before the page becomes interactive, directly improving TTI.' },
  ],
  'Skeletons and perceived-performance techniques': [
    { q: 'What is the difference between a spinner and a skeleton loader in terms of perceived performance?', a: 'A spinner gives no indication of the content\'s eventual shape — it\'s fine for short, unpredictable operations but provides no context. A skeleton loader mimics the actual layout of the incoming content (gray placeholder blocks matching text/image shapes), reducing perceived wait time and avoiding layout shift when the real content arrives, since the user already has a mental model of what\'s coming.' },
    { q: 'What is optimistic UI and how does it relate to perceived performance?', a: 'Optimistic UI immediately applies the expected result of an action (e.g. a "like" button toggling instantly) before the server has actually confirmed it, assuming success — this eliminates the perceived latency of waiting for a network round-trip entirely for the common case, with a rollback mechanism in place for the rare case the action actually fails.' },
  ],
  'Measuring with Lighthouse, WebPageTest, and RUM': [
    { q: 'What is the difference between lab data (Lighthouse) and field data (RUM/CrUX)?', a: 'Lab data is collected in a controlled, simulated environment (Lighthouse running against a fixed network/CPU throttling profile) — reproducible and good for catching regressions in CI, but not representative of real users\' actual diverse devices/networks/conditions. Field data (RUM, or Google\'s Chrome User Experience Report/CrUX) is collected from real users\' actual sessions in production, giving a true picture of real-world performance across the full diversity of your actual user base.' },
    { q: 'How do you set up Real User Monitoring (RUM) to track Core Web Vitals in production?', a: 'Use the web-vitals JS library (or a framework\'s built-in equivalent, like Next.js\'s useReportWebVitals) to capture each metric as it\'s measured in real users\' browsers, and send that data to an analytics/RUM backend (a custom endpoint, or a service like Vercel Speed Insights, Datadog RUM, or Google Analytics) — allowing you to track performance trends over time, segmented by device/geography/connection type, reflecting genuine real-world user experience.' },
  ],

  // React Native Performance
  'New Architecture: JSI, Fabric, TurboModules and why it is faster': [
    { q: 'What performance problems did the old bridge architecture have that JSI/Fabric solve?', a: 'The old bridge forced all JS↔native communication through an asynchronous, JSON-serialized message queue, causing latency for time-sensitive operations, made synchronous native calls impossible, and required all native modules to be eagerly loaded at startup. JSI/Fabric (the New Architecture) allows direct, synchronous, typed calls between JS and native via C++ host objects, lazy module loading, and a more efficient rendering pipeline built for React 18\'s concurrent features.' },
    { q: 'How does JSI eliminate JSON serialization in native module calls?', a: 'JSI lets JavaScript hold direct references to native C++ objects/functions and invoke their methods directly, the same way it would call any JS object\'s method — there\'s no message queue and no need to stringify arguments into JSON and parse them back out on the other side, eliminating the serialization/deserialization overhead the old bridge required for every single cross-boundary call.' },
  ],
  'Hermes engine and bytecode precompilation': [
    { q: 'How does Hermes bytecode precompilation improve cold start time?', a: 'Hermes compiles JS to bytecode ahead-of-time as part of the build pipeline, rather than the device parsing and compiling raw JS text at every app launch — this shifts the compilation cost from every user\'s device on every launch to a single build-time step, meaningfully reducing the time-to-interactive on app cold start.' },
    { q: 'What features of full V8/JSC does Hermes trade off for its mobile-focused optimizations?', a: 'Hermes has a simpler, smaller garbage collector optimized for mobile memory constraints rather than raw throughput, lacks a full JIT compiler (relying instead on its ahead-of-time bytecode compilation and interpretation), and has historically had a smaller/less complete set of some newer JS language features compared to V8 — trade-offs deliberately made to prioritize startup time and memory footprint over peak raw execution speed for long-running computation.' },
  ],
  'Reducing JS <-> native bridge traffic (legacy architecture)': [
    { q: 'What types of operations generate the most bridge traffic?', a: 'High-frequency events like scroll position updates, gesture/pan updates driving animations, frequent layout measurements, and any per-frame communication (e.g. syncing an animated value to native on every frame) generate the most cross-thread traffic, since each of these can fire many times per second, and each firing is a separate serialized message on the legacy bridge.' },
    { q: 'How does batching and avoiding synchronous-looking async calls reduce bridge overhead?', a: 'Batching groups multiple related native operations into a single call rather than many small round trips, amortizing the per-message serialization overhead across more actual work per message. Avoiding code patterns that simulate synchronous behavior over the inherently-async bridge (like awaiting a chain of many small sequential native calls) reduces the total number of round trips needed to complete a given operation.' },
  ],
  'FlatList / FlashList tuning (getItemLayout, windowSize, recycling)': [
    { q: 'How does getItemLayout allow FlatList to skip measurement, and when can you use it?', a: 'getItemLayout lets you tell FlatList the exact height/offset of every item upfront, instead of the list having to measure each item after it renders — this lets FlatList jump directly to any scroll position without rendering everything in between. You can only use it reliably when all items have a known, fixed (or programmatically computable) height.' },
    { q: "How does FlashList's recycler differ from FlatList's virtualization?", a: 'FlashList uses true view recycling — reusing the same native view instances for new data as items scroll into view, similar to Android\'s RecyclerView — rather than mounting/unmounting brand-new native views for every item that enters the viewport, which is what FlatList does. This drastically reduces expensive native view creation/destruction operations during scrolling.' },
  ],
  'Avoiding re-renders in list items (memo, stable callbacks)': [
    { q: 'Why do inline arrow functions in renderItem cause all visible items to re-render on scroll?', a: 'An inline arrow function creates a brand-new function reference on every render of the parent list — even a React.memo-wrapped item component sees a "changed" prop every time the parent re-renders (e.g. on every scroll-triggered state update), defeating the memoization and causing unnecessary re-renders across the whole visible window.' },
    { q: 'How do you create a stable renderItem function using useCallback?', a: 'Wrap renderItem in useCallback with a minimal, stable dependency array, and ensure any per-item callback passed down is similarly stable (often by having the item component accept the item\'s id and a stable top-level handler, computing the specific action internally rather than creating a new closure per item in the parent).' },
  ],
  'Running animations on the UI thread (Reanimated worklets, useNativeDriver)': [
    { q: 'Why does running animations on the JS thread cause jank?', a: 'If an animation\'s per-frame updates are computed on the JS thread, they compete with all other JS work (state updates, event handling, business logic) for that single thread\'s attention — if the JS thread is busy or blocked even briefly, animation frames get dropped or delayed, producing visible jank, since the animation has no dedicated, protected execution path.' },
    { q: 'How does useNativeDriver offload animation to the UI thread?', a: 'Setting useNativeDriver: true sends the entire animation configuration (start/end values, timing/spring parameters) to the native side once, and the native UI thread then drives the frame-by-frame updates directly, without needing to message the JS thread on every single frame — the animation continues smoothly even if the JS thread is simultaneously busy or blocked.' },
    { q: 'How do Reanimated worklets take this further with direct UI-thread execution?', a: 'Worklets are compiled to run directly on the UI thread using a separate lightweight JS runtime that lives there, letting you write arbitrary custom animation/gesture logic (not just a fixed set of pre-declared operations like the old Animated API) that executes entirely on the UI thread — enabling complex, interactive, gesture-driven animations with zero JS-thread involvement during the actual interaction.' },
  ],
  'Image caching and downsizing (FastImage / expo-image)': [
    { q: 'What performance problems does FastImage/expo-image solve over the built-in Image?', a: 'They provide more predictable, aggressive, and configurable caching (separate memory + disk caches with explicit priority levels), better performance for large lists of images (avoiding flicker/re-download on re-render), and built-in support for preloading images ahead of time — the built-in Image component relies on the platform\'s default HTTP cache, offering much less control and consistency across iOS/Android.' },
    { q: 'How do you downsize images before displaying them to reduce memory usage?', a: 'Request an appropriately-sized image from your CDN/backend (many CDNs support on-the-fly resizing via URL parameters) based on the actual display size needed, rather than downloading and decoding a full-resolution original just to display it at a small size — decoding a large image consumes significant memory regardless of its eventual display size, so requesting the right size upfront matters more than CSS/style-based scaling after the fact.' },
  ],
  'Reducing startup time / TTI (inline requires, RAM bundles, lazy screens)': [
    { q: 'What is a RAM bundle and how does it defer parsing of unused modules?', a: 'A RAM (Random Access Memory) bundle splits the JS bundle into individually-addressable module chunks rather than one single monolithic file, allowing the runtime to load and parse only the modules actually needed at a given moment rather than parsing the entire bundle upfront at startup, deferring the cost of unused modules until (if ever) they\'re actually required.' },
    { q: 'How do inline requires delay module evaluation until first use?', a: 'Inline requires move a module\'s require() call from the top of a file (executed immediately at import time) to inside the function/block where it\'s actually used — this defers that module\'s evaluation cost until the first time that code path actually executes, rather than paying the cost for every imported module immediately at app startup regardless of whether it\'s used right away.' },
  ],
  'Detecting and fixing memory leaks': [
    { q: 'What are the most common causes of memory leaks in React Native apps?', a: 'Forgotten event listener/subscription cleanup (not unsubscribing in a useEffect cleanup function), timers (setInterval/setTimeout) not cleared on unmount, closures in native module callbacks retaining large objects longer than needed, and navigation-related retained screens/components that should have been unmounted but are still referenced somewhere.' },
    { q: 'How do you use Flipper or Xcode Instruments to detect a memory leak?', a: 'Flipper\'s memory plugin (or React DevTools\' Profiler for component-level leaks) can show growing memory usage over repeated actions that shouldn\'t accumulate memory (like navigating back and forth). Xcode Instruments\' Allocations/Leaks tool tracks native-level memory allocation over time, letting you take snapshots before/after a repeated action and compare what\'s still retained that shouldn\'t be, tracing the retain path back to the actual leaking reference.' },
  ],
  'Profiling with Flipper, Xcode Instruments, and Android Profiler': [
    { q: 'What profiling capabilities does Flipper provide for React Native?', a: 'A React DevTools integration (component tree inspection, render profiling), a network inspector for viewing all requests/responses, a layout inspector for the native view hierarchy, and crash reporter integration — giving a much richer, RN-aware debugging experience than console logging alone, especially for correlating JS-level and native-level behavior.' },
    { q: 'How do you identify which native component is causing a layout performance issue using Xcode Instruments?', a: 'Use the Core Animation instrument to visualize frame rate/rendering performance in real time while reproducing the janky interaction, and the Time Profiler to see which native functions/view updates are consuming the most CPU time during that window — correlating the timestamps with the specific interaction lets you pinpoint which native view or layout recalculation is the actual bottleneck.' },
  ],

  // Security
  'OWASP Top 10 awareness': [
    { q: 'What are the OWASP Top 10 vulnerabilities and which ones most apply to frontend work?', a: 'The OWASP Top 10 is a regularly-updated list of the most critical web application security risks (broken access control, cryptographic failures, injection, insecure design, security misconfiguration, vulnerable components, authentication failures, data integrity failures, logging failures, and SSRF). For frontend work, injection (specifically XSS), broken access control (client-side authorization checks that aren\'t backed by real server-side enforcement), vulnerable/outdated components (third-party npm packages), and authentication failures are the most directly relevant.' },
    { q: 'How does knowing the OWASP Top 10 inform your daily development practices?', a: 'It shapes habits like always sanitizing/escaping user-generated content before rendering, never trusting client-side-only authorization checks, keeping dependencies updated and audited, avoiding storing sensitive tokens insecurely, and treating security review as a standard part of code review rather than an afterthought — essentially building a mental checklist of common failure modes to actively guard against as you write code.' },
  ],
  'XSS (stored, reflected, DOM-based) and output sanitization (DOMPurify)': [
    { q: 'What are the three types of XSS, and how does each differ in how the payload is delivered?', a: 'Stored XSS: malicious script is persistently saved on the server (e.g. in a comment) and served to every subsequent visitor. Reflected XSS: malicious script is embedded in a request (like a URL parameter) and immediately reflected back into the response without proper escaping. DOM-based XSS: the vulnerability exists purely client-side, in JS code that unsafely inserts untrusted data into the DOM, with no server involvement in the payload delivery at all.' },
    { q: 'Why is DOMPurify safer than filtering HTML with a regex?', a: 'HTML is not a regular language, so regex-based sanitization is fundamentally unreliable — attackers can craft malformed or unusually-nested HTML that slips past a regex filter while still being interpreted as valid, dangerous markup by the actual browser parser. DOMPurify uses a real HTML parser to build an actual DOM tree and then strips dangerous elements/attributes based on that correctly-parsed structure, matching how the browser itself will interpret the content.' },
    { q: "How does React's default rendering (JSX) protect against XSS?", a: 'JSX automatically escapes any values interpolated into text content or attributes before rendering, converting special characters like `<` and `>` into their safe HTML entity equivalents — this means simply rendering `{userInput}` in JSX is safe by default; XSS only becomes possible if you explicitly bypass this protection via dangerouslySetInnerHTML (aptly named as a warning) with unsanitized content.' },
  ],
  'CSRF and defenses (SameSite cookies, anti-CSRF tokens)': [
    { q: 'How does a CSRF attack work, and why do SameSite cookies help prevent it?', a: 'A victim logged into a legitimate site (with an active session cookie) visits a malicious page that automatically submits a request to the legitimate site\'s state-changing endpoint — since browsers automatically attach cookies to any request to that domain regardless of origin, the server sees what looks like a genuine authenticated request. SameSite cookies prevent the browser from sending that cookie along with cross-site-initiated requests, neutralizing the attack since the session cookie simply won\'t be attached.' },
    { q: 'What is the difference between SameSite=Strict and SameSite=Lax?', a: 'SameSite=Strict blocks the cookie from being sent with any cross-site request whatsoever, even a simple top-level navigation (clicking a link from another site) — this can break legitimate cross-site linking flows. SameSite=Lax (the modern browser default) still allows the cookie on top-level navigations (like following a link) but blocks it for background cross-site requests (form submissions via fetch, image loads) — a more practical middle ground for most use cases.' },
    { q: 'How do anti-CSRF tokens work alongside SameSite cookies?', a: 'An anti-CSRF token is a unique, unpredictable value embedded in a form/request (often via a hidden field or custom header) that the server verifies matches a value tied to the user\'s session — since an attacker\'s malicious page can\'t read or predict this token (due to the same-origin policy preventing them from reading the legitimate page\'s content), they can\'t forge a valid request even if they can trigger one, providing defense-in-depth alongside SameSite cookies.' },
  ],
  'CORS — how it works and configuring it correctly': [
    { q: 'What is the Same-Origin Policy and how does CORS relax it?', a: 'The Same-Origin Policy is the browser\'s default restriction preventing a page from making requests to a different origin (different protocol/domain/port) and reading the response. CORS is a mechanism for a server to explicitly opt certain origins into being permitted to make cross-origin requests and read the response, via specific response headers (Access-Control-Allow-Origin and related headers) — it\'s a controlled relaxation, not a removal, of the underlying same-origin protection.' },
    { q: 'What triggers a CORS preflight request?', a: 'A preflight (an automatic OPTIONS request) is triggered for "non-simple" cross-origin requests — using an HTTP method other than GET/HEAD/POST, custom request headers beyond the small allowed simple set, or a Content-Type other than a few specific simple values — the browser sends this OPTIONS request first to confirm the server actually permits the real request before sending it.' },
    { q: 'What are the risks of setting `Access-Control-Allow-Origin: *`?', a: 'It allows literally any origin to make cross-origin requests to your API and read the response — fine for genuinely public, non-sensitive data endpoints, but dangerous for any endpoint returning user-specific or sensitive data, since any malicious site could then read that data on behalf of a visiting user (though notably, `*` cannot be combined with credentialed requests, which require an explicit, specific origin rather than the wildcard).' },
  ],
  'Content Security Policy (CSP) and Trusted Types': [
    { q: 'What does a Content Security Policy protect against?', a: 'CSP is a browser-enforced allowlist mechanism, set via an HTTP header, that restricts what sources of content (scripts, styles, images, fonts) a page is permitted to load and execute — it\'s primarily a defense-in-depth measure against XSS, since even if an attacker manages to inject a malicious script tag, a properly configured CSP can block that injected script from actually executing if it doesn\'t come from an allowed source.' },
    { q: 'How would you configure a strict CSP that allows inline React event handlers?', a: 'React\'s event handlers (onClick, etc.) are actually attached via JS event delegation, not inline HTML attributes, so they don\'t require an `unsafe-inline` script-src exception — a strict CSP typically only needs to allow your actual script bundle\'s source (script-src \'self\' plus your CDN if applicable) and can use a nonce or hash-based approach for any genuinely inline scripts (like a small bootstrapping script), avoiding the broad, XSS-defeating `unsafe-inline` directive entirely.' },
    { q: 'What are Trusted Types and how do they harden against DOM XSS?', a: 'Trusted Types is a browser API that restricts dangerous DOM sink functions (innerHTML, eval, etc.) to only accept specially-typed, validated objects rather than arbitrary strings — enforced via CSP, it forces all HTML/script injection points in your app to go through explicit, auditable sanitization functions, making it structurally much harder for a DOM-based XSS vulnerability to succeed even if unsafe-looking code exists somewhere in a large codebase.' },
  ],
  'Auth strategies: sessions vs JWT, refresh tokens, rotation': [
    { q: 'What are the trade-offs between session cookies and JWTs for authentication?', a: 'Session cookies require server-side session storage (a database/cache lookup on every request) but are easy to revoke instantly (just delete the session record) and keep no sensitive data on the client. JWTs are self-contained and stateless (no server-side lookup needed to validate), scaling more easily across distributed servers, but are harder to revoke before expiration (since the server doesn\'t track them) and expose their payload (though not secret, since it\'s just base64-encoded, not encrypted) to anyone who can read the token.' },
    { q: 'What is refresh token rotation and why does it improve security?', a: 'Refresh token rotation issues a brand-new refresh token every time the current one is used to obtain a new access token, invalidating the old one — if a refresh token is stolen and used by an attacker, the legitimate user\'s next refresh attempt (using the now-invalidated original token) fails, signaling token theft and allowing the system to revoke the entire token family, limiting the window of exploitation compared to a long-lived, never-rotated refresh token.' },
    { q: 'How do silent refresh and refresh token rotation work together?', a: 'Silent refresh automatically obtains a new access token in the background (before the current one expires) without requiring the user to re-authenticate, typically using the refresh token — combined with rotation, each silent refresh call both extends the session and issues a fresh refresh token, continuously "rolling" the valid refresh token forward while invalidating each previous one, minimizing the value of any single stolen token.' },
  ],
  'Token storage: httpOnly cookies vs localStorage trade-offs': [
    { q: 'Why is storing JWTs in localStorage a security concern?', a: 'localStorage is fully accessible to any JavaScript running on the page — if an attacker achieves XSS (even a relatively minor injection point), they can trivially read and exfiltrate any token stored in localStorage, giving them full ability to impersonate the user, since there\'s no barrier between "JS can run on this page" and "JS can read this token."' },
    { q: 'How do httpOnly, Secure, and SameSite cookie flags protect auth tokens?', a: 'httpOnly makes the cookie completely inaccessible to JavaScript (document.cookie can\'t read it), neutralizing token theft via XSS. Secure ensures the cookie is only ever sent over HTTPS, preventing interception over an unencrypted connection. SameSite restricts when the cookie is sent with cross-site requests, mitigating CSRF — together these three flags substantially harden cookie-based token storage against the most common attack vectors.' },
    { q: 'What are the trade-offs of httpOnly cookies vs localStorage for a SPA?', a: 'httpOnly cookies are much safer against XSS-based token theft but require more careful CSRF protection (SameSite + anti-CSRF tokens) and can be more awkward for cross-origin API setups (needing explicit CORS credential configuration). localStorage is simpler to work with from JS (readable/writable directly) and works easily across different API origins, but is fundamentally vulnerable to any XSS on the page — for genuinely sensitive auth tokens, httpOnly cookies are generally the more security-conscious default choice.' },
  ],
  'OAuth 2.0 and OpenID Connect flows (PKCE)': [
    { q: 'What is the Authorization Code flow with PKCE, and why is PKCE required for SPAs?', a: 'The client generates a random "code verifier" and sends its hashed version (the "code challenge") with the initial authorization request; after the user authenticates, the authorization server returns a code that can only be exchanged for tokens by presenting the original code verifier, which the authorization server checks against the challenge. PKCE is required for SPAs (and mobile apps) because they\'re "public clients" that can\'t securely store a client secret — PKCE proves the token-exchange request comes from the same client that initiated the flow, without needing a secret.' },
    { q: 'What is the difference between OAuth 2.0 and OpenID Connect?', a: 'OAuth 2.0 is an authorization framework — it\'s about granting a client access to a resource (an API) on a user\'s behalf, producing an access token. OpenID Connect is an identity layer built on top of OAuth 2.0, specifically standardizing authentication (verifying who the user is) by adding a standardized ID token (a JWT containing user identity claims) alongside the OAuth access token — OAuth alone says nothing officially about user identity, which is exactly the gap OIDC fills.' },
    { q: 'Why is the Implicit flow deprecated for SPAs?', a: 'The Implicit flow returned access tokens directly in the URL fragment after redirect, with no token-exchange step at all — this exposed tokens to browser history, referrer headers, and any script with URL access, with no mechanism (like PKCE) to verify the token request\'s legitimacy; the Authorization Code flow with PKCE is now universally recommended instead, since it never exposes tokens in the URL and adds proof-of-possession via PKCE.' },
  ],
  'HTTPS/TLS, HSTS, and secure headers': [
    { q: 'What does HTTP Strict Transport Security (HSTS) do?', a: 'HSTS is a response header that tells the browser to automatically convert all future requests to that domain to HTTPS, even if the user types or clicks an http:// link, for a specified duration — this prevents a whole class of downgrade/man-in-the-middle attacks that rely on tricking a user into an initial unencrypted connection before redirecting to HTTPS.' },
    { q: 'What security headers should a production web app set (X-Frame-Options, X-Content-Type, etc.)?', a: 'X-Frame-Options (or the CSP frame-ancestors directive) to prevent clickjacking via iframe embedding, X-Content-Type-Options: nosniff to prevent MIME-type sniffing attacks, a Content-Security-Policy for XSS defense-in-depth, Referrer-Policy to control how much URL information leaks to other sites via the referrer, and Strict-Transport-Security (HSTS) — collectively forming a baseline security header configuration most production apps should include.' },
  ],
  'Dependency/supply-chain security (npm audit, Snyk, Dependabot, lockfiles)': [
    { q: 'Why are lockfiles (package-lock.json, yarn.lock) important for supply chain security?', a: 'Lockfiles pin the exact resolved version (and often a content hash) of every dependency in your dependency tree, ensuring every install produces byte-for-byte identical dependencies regardless of when or where it runs — without a lockfile, a semver-range dependency could silently resolve to a newer, potentially compromised version between installs, making your build non-reproducible and vulnerable to a compromised package update slipping in unnoticed.' },
    { q: 'How do npm audit and Dependabot differ in how they surface vulnerabilities?', a: 'npm audit is an on-demand (or CI-triggered) command that checks your current dependency tree against a vulnerability database and reports known issues at that moment. Dependabot is a continuous, automated GitHub service that monitors your dependencies over time and automatically opens pull requests to bump vulnerable dependencies to a patched version as new vulnerabilities are discovered, providing ongoing, proactive monitoring rather than a one-time check.' },
  ],
  'Injection awareness (SQL/NoSQL, command)': [
    { q: "How does injection attack the client-side and what is the frontend's responsibility?", a: 'While SQL/NoSQL/command injection are primarily backend concerns (since they involve constructing queries/commands from untrusted input), the frontend\'s responsibility is to never assume client-side validation is sufficient security (it\'s only a UX convenience — a malicious actor can bypass the frontend entirely and hit the API directly), and to be aware that any user input the frontend forwards to a backend could be an injection vector if the backend doesn\'t properly parameterize/sanitize it.' },
    { q: 'How does parameterized queries/prepared statements prevent SQL injection at the backend?', a: 'Parameterized queries separate the SQL query structure (fixed at write time) from the actual data values (bound in as parameters at execution time) — the database driver ensures parameter values are always treated strictly as data, never as executable SQL syntax, regardless of what characters they contain, structurally preventing an attacker\'s input from ever being interpreted as part of the query logic itself.' },
  ],
  'Mobile: secure storage (Keychain / Keystore), Keychain vs AsyncStorage': [
    { q: 'Why is AsyncStorage not appropriate for storing auth tokens on mobile?', a: 'AsyncStorage persists data unencrypted on disk (as plain files/SQLite in the app\'s sandbox) — while the OS sandbox provides some protection on a non-compromised device, the data is far more easily extracted on a rooted/jailbroken device or via certain backup/debugging vectors compared to storage specifically designed for secrets, making it inappropriate for sensitive tokens.' },
    { q: 'How does the iOS Keychain / Android Keystore differ from AsyncStorage in terms of security?', a: 'The Keychain (iOS) and Keystore (Android) are OS-level secure storage systems specifically designed for sensitive data, offering hardware-backed encryption on supported devices, biometric-gated access options, and stronger isolation guarantees even against a rooted/jailbroken device in many cases — a fundamentally different security posture than AsyncStorage\'s plain, unencrypted file-based storage.' },
  ],
  'Mobile: SSL/certificate pinning': [
    { q: 'What is certificate pinning and what attack does it prevent?', a: 'Certificate pinning hardcodes (pins) the expected server certificate (or public key) into the app, so the app only trusts connections presenting that exact specific certificate, rather than trusting any certificate signed by a certificate authority in the device\'s trust store — this prevents man-in-the-middle attacks where an attacker (or a compromised/malicious CA) presents a technically-valid-but-illegitimate certificate to intercept traffic.' },
    { q: 'What are the operational trade-offs of pinning certificates in a mobile app?', a: 'If the server\'s certificate needs to be rotated/renewed (which happens periodically) without a corresponding app update including the new pin, all instances of the app suddenly can\'t connect at all — this creates an operational coupling between certificate rotation and app release cycles, requiring careful coordination (like pinning to a longer-lived intermediate CA, or supporting multiple pins during a transition period) to avoid breaking the app for all users on a routine cert renewal.' },
  ],

  // Offline, Networking & Data Sync
  'Offline-first architecture and graceful degradation': [
    { q: 'What is the difference between offline-first and offline-capable?', a: 'Offline-capable means the app can tolerate being offline without crashing, typically showing an error/degraded state until connectivity returns. Offline-first means the app is architected with local data as the primary source of truth, fully functional for reading and often writing while offline, syncing with the server opportunistically when connectivity is available — a fundamentally different architecture, not just a fallback error state.' },
    { q: 'How would you design a React Native app to work fully offline?', a: 'Use a local-first database (WatermelonDB, Realm, or SQLite) as the app\'s primary data source that all UI reads from directly, sync changes to/from the server in the background via a queue that processes when connectivity is available, implement conflict resolution for changes made offline that conflict with server-side changes, and design the UI to never block on network availability for core functionality.' },
  ],
  'Service Workers and caching strategies (cache-first, network-first, SWR)': [
    { q: 'What are the main Service Worker caching strategies and when do you use each?', a: 'Cache-first: check cache, fall back to network — best for static assets that rarely change (fonts, icons). Network-first: try network, fall back to cache on failure — best for content that should be fresh when possible but tolerable stale when offline. Stale-while-revalidate: serve from cache immediately while fetching a fresh version in the background for next time — best for content where instant response matters but eventual freshness is still desired.' },
    { q: 'How does the stale-while-revalidate caching strategy balance freshness and speed?', a: 'It immediately returns the cached (potentially stale) response for instant perceived performance, while simultaneously firing a background fetch to update the cache with fresh data for the next request — users get instant responses on every visit, and data gradually converges toward freshness over successive requests, rather than forcing a trade-off between speed and freshness on any single request.' },
  ],
  'PWA fundamentals (manifest, installability, app shell)': [
    { q: 'What makes a web app installable as a PWA?', a: 'A valid web app manifest (JSON file describing the app\'s name, icons, start URL, display mode), served over HTTPS, with a registered Service Worker providing at least basic offline functionality — meeting these baseline criteria triggers the browser\'s "add to home screen"/install prompt, letting the PWA behave like a native app icon on the user\'s device.' },
    { q: 'What is the app shell architecture and what problem does it solve?', a: 'The app shell is the minimal, static HTML/CSS/JS needed to render the basic UI structure (navigation, layout skeleton) — cached aggressively so it loads instantly (even offline), with actual dynamic content loaded/populated afterward. It solves the problem of slow, network-dependent initial loads by ensuring the app\'s basic "frame" is always instantly available, with only the content itself needing a network round-trip.' },
  ],
  'Local persistence: IndexedDB, SQLite, MMKV, Realm, WatermelonDB': [
    { q: 'When would you choose IndexedDB over localStorage?', a: 'IndexedDB supports structured, indexed, queryable data (transactions, indexes for efficient lookups, larger storage limits) suitable for genuinely database-like needs — offline-first data caching, storing large datasets. localStorage is simpler but limited to small amounts of synchronous, string-only key-value data, unsuitable for anything requiring querying, indexing, or larger data volumes.' },
    { q: 'What makes WatermelonDB or Realm appropriate for large relational datasets in a mobile app?', a: 'Both provide a genuine relational/object database with lazy loading, efficient querying, and reactive observation of query results — designed specifically for large datasets (tens of thousands of records) where a simple key-value store (AsyncStorage/MMKV) would be too slow to query/filter, offering the kind of indexed, structured querying a real database provides while remaining performant on mobile hardware constraints.' },
  ],
  'Optimistic UI updates and rollback': [
    { q: 'Walk through implementing an optimistic delete with a rollback on failure.', a: 'Snapshot the current list state before the delete; immediately remove the item from the UI (optimistically assuming success); fire the actual delete API request in the background; if it succeeds, do nothing further (the UI is already correct); if it fails, restore the snapshotted state (re-inserting the item) and show an error message, reverting the UI to accurately reflect what actually happened server-side.' },
    { q: "How does React Query's onMutate / onError / onSettled API support optimistic updates?", a: 'onMutate fires before the mutation request is sent, where you apply the optimistic change to the cache and return a "context" object (typically a snapshot for rollback). onError fires if the mutation fails, receiving that context to roll back the optimistic change. onSettled fires regardless of success/failure, typically used to refetch/reconcile with the server\'s actual current state — together these three hooks provide a structured, complete lifecycle for implementing optimistic updates correctly.' },
  ],
  'Background sync and offline mutation queues': [
    { q: 'How would you queue mutations made while offline and sync them when connectivity returns?', a: 'Persist pending mutations (the operation type + payload) to local storage as they\'re made while offline, listen for connectivity restoration (via NetInfo on mobile, or the online/offline events on web), and on reconnect, process the queue in order, removing each mutation from the queue only after its corresponding server request succeeds — handling potential conflicts if the server-side data changed in the meantime.' },
    { q: 'What is the Background Sync API in Service Workers?', a: 'Background Sync lets a web app register a deferred task that the browser guarantees to run once connectivity is restored, even if the page itself isn\'t open at that moment — useful for ensuring a queued offline action (like sending a message) eventually completes without requiring the user to keep the tab open and manually retry once they\'re back online.' },
  ],
  'Conflict resolution and data reconciliation (last-write-wins, CRDTs overview)': [
    { q: 'What are common conflict resolution strategies for offline-first data sync?', a: 'Last-write-wins (the most recent timestamped change simply overwrites earlier conflicting changes — simple but can silently lose data), field-level merging (merging non-conflicting field changes from different sources, only conflicting on genuinely overlapping fields), and CRDTs (data structures mathematically guaranteed to merge conflict-free regardless of the order changes arrive) — the right choice depends on how much data-loss risk is acceptable versus implementation complexity.' },
    { q: 'What is a CRDT and when would you need one over last-write-wins?', a: 'A CRDT (Conflict-free Replicated Data Type) is a data structure specifically designed so concurrent, independent modifications from different sources can always be merged deterministically and correctly, with no coordination needed and no data loss — you\'d need one over simple last-write-wins for genuinely collaborative, concurrent-editing use cases (like a shared document or collaborative list) where silently discarding one user\'s changes in favor of another\'s (as last-write-wins would) is unacceptable.' },
  ],
  'Retry with exponential backoff and jitter': [
    { q: 'Why add jitter to exponential backoff?', a: 'Without jitter, many clients that failed at roughly the same time (e.g. during a server outage) would all retry at exactly the same predictable intervals, creating synchronized "thundering herd" spikes of retry traffic that can overwhelm a recovering server. Adding a small random jitter to each retry delay spreads out the retry timing across clients, smoothing out the load instead of creating synchronized traffic spikes.' },
    { q: 'Implement a simple retry with exponential backoff for a fetch call.', a: '`async function retryFetch(url, retries = 3, delay = 1000) { try { return await fetch(url); } catch (err) { if (retries === 0) throw err; await new Promise(r => setTimeout(r, delay + Math.random() * delay)); return retryFetch(url, retries - 1, delay * 2); } }` — each failed attempt doubles the delay for the next attempt (exponential) and adds randomized jitter, up to a maximum retry count.' },
  ],
  'Request deduplication and caching (React Query, SWR, Apollo, RTK Query)': [
    { q: 'How does React Query deduplicate simultaneous requests for the same key?', a: 'When multiple components call useQuery with the identical query key at roughly the same time, React Query recognizes they\'re requesting the same data and only actually fires one underlying network request, sharing the result (and its loading/error state) across all the components that requested it, rather than each component independently triggering its own redundant fetch.' },
    { q: 'What is the difference between request deduplication and response caching?', a: 'Deduplication prevents multiple simultaneous requests for the same data from all hitting the network separately (combining them into one in-flight request). Caching stores the result of a completed request so a later request for the same data can be served instantly from the cache without hitting the network at all — deduplication addresses concurrent redundant requests, caching addresses sequential redundant requests over time.' },
  ],
  'Cache invalidation strategies (the hard problem)': [
    { q: 'What are the different cache invalidation strategies and their trade-offs?', a: 'Time-based (TTL) expiration is simple but can serve stale data within the TTL window or unnecessarily refetch fresh data too early. Manual/explicit invalidation (invalidating specific cache entries after a known mutation) is precise but requires the developer to correctly track every place that could affect cached data. Tag-based invalidation groups related cache entries so a single mutation can invalidate everything logically affected, balancing precision and maintainability better than either purely manual or purely time-based approaches alone.' },
    { q: 'How does tag-based invalidation (React Query queryClient.invalidateQueries) work?', a: 'You associate query keys with logical groupings/patterns (e.g. all queries under `["todos"]`), and calling `queryClient.invalidateQueries({ queryKey: ["todos"] })` marks every matching cached query as stale, triggering a background refetch for any currently-mounted components using those queries — letting a single mutation (like adding a todo) correctly invalidate all related cached views without needing to know every individual query key that might be affected.' },
  ],
  'HTTP caching headers (ETag, Cache-Control, Last-Modified)': [
    { q: 'What is the difference between ETag and Last-Modified for conditional requests?', a: 'ETag is an opaque, content-based hash/identifier — the server compares the client\'s sent ETag against the current resource\'s ETag to determine if content actually changed, which is precise even for changes that don\'t affect a timestamp. Last-Modified is a timestamp-based approach — less precise (can\'t detect a sub-second change, or a change that happens to occur without updating a timestamp), but simpler and requires less server-side computation than generating a content hash.' },
    { q: "What does `Cache-Control: no-cache` actually do (it doesn't skip caching)?", a: 'Despite its name, no-cache does NOT prevent caching — it means the cached response CAN be stored, but MUST be revalidated with the server (via a conditional request using ETag/Last-Modified) before being used, every time, rather than being used directly without a network round-trip; to actually prevent any caching at all, you need `no-store` instead.' },
  ],
  'Real-time: WebSockets, Server-Sent Events, long polling': [
    { q: 'What are the trade-offs between WebSockets, SSE, and long polling?', a: 'WebSockets provide full-duplex (bidirectional) communication over a single persistent connection, ideal for interactive real-time apps (chat, collaborative editing) but require more server-side connection management complexity. SSE (Server-Sent Events) is simpler, one-directional (server-to-client only) over regular HTTP, well-suited for live feeds/notifications where the client doesn\'t need to send data back over the same channel. Long polling (repeatedly making a request that the server holds open until new data is available) works over plain HTTP with no special protocol needed, but is less efficient than either WebSockets or SSE due to repeated connection overhead.' },
    { q: 'When would you choose SSE over WebSockets for real-time updates?', a: 'When communication is genuinely one-directional (server pushing updates to the client, with the client not needing to send data back over the same real-time channel) — SSE is simpler to implement (works over plain HTTP, automatically reconnects, no special server infrastructure needed beyond a standard HTTP server), making it a good fit for live notification feeds, stock tickers, or progress updates where full bidirectional WebSocket complexity isn\'t warranted.' },
  ],
  'REST vs GraphQL vs tRPC trade-offs': [
    { q: 'What are the main trade-offs between REST and GraphQL for a frontend team?', a: 'REST is simpler to understand, cache (via standard HTTP caching), and debug, but often leads to over-fetching (getting more data than needed) or under-fetching (needing multiple round trips) for complex UI needs. GraphQL lets the client precisely specify exactly the data it needs in a single request, reducing over/under-fetching, but adds complexity (schema design, resolver implementation, more complex caching) and can make it harder to leverage standard HTTP-level caching infrastructure.' },
    { q: 'What does tRPC offer over REST or GraphQL for a TypeScript full-stack app?', a: 'tRPC provides end-to-end type safety without any code generation step or schema language — your frontend directly imports and calls your backend\'s TypeScript function signatures, with full autocomplete and compile-time type checking across the client-server boundary, something REST (which needs manual/generated typing of responses) and GraphQL (which needs a separate schema and codegen step) both require extra tooling to achieve, at the cost of tRPC only working within a single, shared TypeScript codebase.' },
  ],
  'Pagination patterns (offset, cursor, infinite scroll)': [
    { q: 'What are the trade-offs between offset-based and cursor-based pagination?', a: 'Offset-based pagination (page=2&limit=20) is simple to implement and allows jumping to arbitrary pages, but can produce inconsistent results if items are inserted/deleted between page requests (items shifting position, causing duplicates or skips). Cursor-based pagination (using an opaque pointer to "continue from here") is more robust against concurrent data changes and performs better on large datasets (avoiding the cost of skipping N rows), but doesn\'t easily support jumping directly to an arbitrary page number.' },
    { q: 'How do you implement infinite scroll with cursor-based pagination?', a: 'Use an IntersectionObserver (or a scroll listener) to detect when the user nears the bottom of the currently-loaded content, and fetch the next page using the cursor returned by the previous page\'s response, appending the new results to the existing list — React Query\'s useInfiniteQuery hook handles this pattern directly, managing the accumulated pages and providing a fetchNextPage function tied to the cursor progression.' },
  ],

  // Design Patterns & Architecture
  'SOLID principles': [
    { q: 'Explain the Single Responsibility Principle with a React component example.', a: 'A component should have one reason to change — a component that both fetches data AND handles complex presentation logic violates SRP, since a change to the API shape and a change to the visual design are two unrelated reasons to modify the same file. Splitting into a data-fetching custom hook and a purely presentational component gives each piece exactly one responsibility and one reason to change.' },
    { q: 'How does the Open/Closed Principle apply to component design?', a: 'A component should be open for extension but closed for modification — designing a component to accept composition (children, render props, slots) or configuration (variant props) lets consumers extend its behavior/appearance without needing to modify the component\'s own internal source code, which matters especially for shared/design-system components used across many teams.' },
    { q: 'How does Dependency Inversion apply to how React components consume services?', a: 'Rather than a component directly importing and calling a concrete implementation (a specific API client, a specific analytics library), it depends on an abstraction (a prop, a context, an injected hook) that\'s provided from outside — this lets you swap implementations (a mock for testing, a different provider) without modifying the component itself, decoupling the component from a specific concrete dependency.' },
  ],
  'DRY, KISS, YAGNI, and separation of concerns': [
    { q: 'When does following DRY actually make code worse?', a: 'When two pieces of code look similar but represent genuinely different concerns that happen to coincide today — abstracting them into one shared function couples them together, so a future change needed for only one use case forces you to either break the abstraction back apart or add conditional branches that make the "shared" code harder to understand than if it had simply stayed duplicated; premature or overly-eager DRY-ing can create worse coupling than a small amount of harmless duplication.' },
    { q: 'What does YAGNI mean and how does it apply to API design for components?', a: 'YAGNI ("You Aren\'t Gonna Need It") means not building speculative flexibility/features for hypothetical future requirements that may never materialize. Applied to component API design, it means not adding a dozen configuration props "just in case" — start with the minimal API that satisfies actual current needs, and extend it later when a genuine new requirement arises, rather than guessing at future needs and over-engineering the initial API.' },
  ],
  'Common GoF patterns in FE (Singleton, Factory, Observer, Strategy, Facade, Adapter, Decorator, Proxy)': [
    { q: 'What GoF patterns do you recognize in the React ecosystem?', a: 'Observer manifests in React\'s own state/subscription model and in libraries like Redux/Zustand (components subscribe to store changes). Factory appears in component libraries providing a "create" function to build configured component instances. Facade shows up in SDK wrapper modules simplifying a complex third-party library\'s API into a simpler, app-specific interface. Higher-Order Components are essentially a Decorator pattern, wrapping a component with additional behavior.' },
    { q: 'How does the Observer pattern manifest in React state management or event systems?', a: 'A store (Redux, Zustand, a Context provider) maintains a list of subscribers (components) and notifies them whenever its state changes, letting each subscriber re-render/react to that change — this is a direct implementation of the Observer pattern: a subject (the store) maintaining and notifying a set of observers (subscribed components) without either side needing to know the specific details of the other.' },
    { q: 'How does the Facade pattern apply to how you wrap third-party libraries?', a: 'Wrapping a complex third-party library (an analytics SDK, a payment provider\'s API) behind a simplified, app-specific interface (`analytics.trackEvent(name, props)` instead of directly calling the vendor\'s more complex, vendor-specific API everywhere) provides a Facade — the rest of your app depends only on your simplified interface, letting you swap the underlying vendor/implementation later by changing just the facade, without touching every call site.' },
  ],
  'HOC vs render props vs custom hooks (evolution)': [
    { q: 'Why did the community move from HOCs to render props to custom hooks?', a: 'HOCs created "wrapper hell" (many nested wrapper components, obscuring where props actually come from) and had naming collision/ref-forwarding complications. Render props avoided the extra component-wrapping-layer issue somewhat but introduced deep JSX nesting for stacking multiple render-prop-based behaviors. Custom hooks (once React introduced Hooks) solved both problems entirely — reusable logic composes as plain function calls inside a component body, with no extra wrapping component or JSX nesting layer at all.' },
    { q: 'Are there still valid use cases for HOCs in 2024?', a: 'They\'re rare but still occasionally used for cross-cutting concerns that need to intercept/control a component\'s actual rendering from outside (conditionally rendering an entirely different component, or injecting props before the wrapped component even mounts) — something a hook, which runs inside the component rather than around it, structurally cannot do; most modern use cases are adequately served by hooks instead, though.' },
  ],
  'Compound components and controlled/uncontrolled API design': [
    { q: 'What is the compound component pattern and what makes it flexible?', a: 'Several components work together as a cohesive unit, implicitly sharing state (usually via Context) while giving the consumer flexible control over structure/composition — e.g. `<Select><Select.Option/><Select.Option/></Select>` — it\'s flexible because the consumer controls exactly what\'s rendered and in what arrangement, rather than being constrained by a single monolithic component\'s fixed set of configuration props.' },
    { q: 'How do you design a component to support both controlled and uncontrolled modes?', a: 'Accept both `value`/`onChange` (for controlled usage) and `defaultValue` (for uncontrolled usage) as props, maintaining internal state initialized from defaultValue but only actually using that internal state when `value` isn\'t explicitly provided by the caller — checking whether value is defined determines which mode is active, mirroring how native HTML form elements themselves support both usage patterns.' },
  ],
  'State machines for complex flows (XState)': [
    { q: 'When does a state machine outperform ad-hoc state management with booleans?', a: 'When a component/flow has many interrelated boolean flags (isLoading, isError, isSuccess, isEditing) that can produce invalid/impossible combinations if not carefully coordinated by hand (e.g. isLoading and isError both true simultaneously, which shouldn\'t be possible) — a state machine makes only valid states and valid transitions between them representable at all, eliminating an entire class of "impossible state" bugs that ad-hoc boolean flags are prone to.' },
    { q: 'What is the actor model in XState v5?', a: 'XState v5 models state machines as "actors" — independent, communicating units that can spawn child actors, send/receive messages, and manage their own isolated state — this lets you compose complex systems out of smaller, independently-testable state machines communicating via message passing, rather than one single, monolithic machine trying to model an entire complex flow\'s state all at once.' },
  ],
  'Dependency injection and inversion of control': [
    { q: "How does React's Context API implement a form of dependency injection?", a: 'A component doesn\'t need to know or directly import a specific concrete service/value — it simply calls useContext and receives whatever was provided further up the tree, letting the actual implementation be swapped (a mock service in tests, a different theme in Storybook) without modifying the consuming component itself — this is fundamentally the same concept as dependency injection in other languages/frameworks, just implemented via React\'s component tree rather than an explicit DI container.' },
    { q: 'How does inverting control (passing behavior as props/callbacks) improve testability?', a: 'A component that accepts its behavior (an onSubmit callback, a data-fetching function) as a prop rather than hardcoding a specific implementation internally can be tested in isolation by passing a simple mock/stub function and asserting on how it was called — without inversion of control, testing would require mocking out whatever concrete dependency (a real API call, a specific library) the component directly and rigidly depends on internally.' },
  ],
  'Flux / Redux unidirectional data flow; MVC / MVVM': [
    { q: 'What problem did the Flux architecture solve over MVC for large front-end apps?', a: 'In MVC, models and views could update each other bidirectionally in complex, hard-to-trace ways, especially as an app grows (a view updating a model, which updates another model, which updates another view, in a tangled web) — Flux enforced a strict, unidirectional data flow (action → dispatcher → store → view), making the sequence of causes and effects in a state change always traceable in one predictable direction, dramatically easing debugging in large, complex applications.' },
    { q: 'How does unidirectional data flow make debugging easier?', a: 'Since state can only change through one well-defined path (a dispatched action processed by a reducer), you can always answer "what caused this state change?" by looking at exactly one place — the reducer\'s handling of that action — rather than needing to trace through an arbitrary, potentially circular web of bidirectional updates that could have originated from many different possible sources.' },
  ],
  'Monorepo (Nx, Turborepo) vs polyrepo trade-offs': [
    { q: 'What are the benefits of a monorepo for a frontend platform team?', a: 'Shared code (design systems, utility libraries) can be referenced directly without publishing/versioning a separate package for every change, atomic cross-cutting changes (updating a shared component and all its consumers) happen in a single commit/PR instead of a coordinated multi-repo release, and consistent tooling/CI configuration is enforced across all projects rather than drifting independently per repo.' },
    { q: 'What are the main challenges of a monorepo at scale, and how do Nx and Turborepo address them?', a: 'Challenges: CI build/test times growing as the codebase grows if every change re-tests the entire repo, and coordinating ownership/access across many teams in one shared repo. Nx and Turborepo address the build-time problem with intelligent task caching (only rebuilding/retesting what actually changed and its dependents) and remote/distributed caching shared across the team and CI, dramatically reducing redundant work compared to naively rebuilding everything on every change.' },
  ],
  'Micro-frontends and module federation': [
    { q: 'What problem do micro-frontends solve, and what complexity do they introduce?', a: 'Micro-frontends let independent teams develop, deploy, and scale separate parts of a large application independently, avoiding the bottleneck of one giant monolithic frontend requiring full-app coordination for every deploy. They introduce complexity around shared dependency versioning, consistent styling/UX across independently-built pieces, cross-team communication/contracts, and runtime integration overhead (loading and coordinating multiple separately-built bundles at runtime).' },
    { q: 'What is Webpack Module Federation and how does it enable runtime composition of micro-frontends?', a: 'Module Federation lets separately-built and separately-deployed JavaScript bundles dynamically load code from each other at runtime, sharing common dependencies (like React) to avoid duplication — one app (the "host") can dynamically import a component exposed by another independently-deployed app (a "remote") at runtime, enabling true micro-frontend composition without needing to bundle everything together at build time.' },
  ],
  'Designing for testability and maintainability': [
    { q: 'How does separating business logic from UI components improve testability?', a: 'Business logic extracted into plain functions or hooks (independent of any specific rendering) can be tested directly with simple input/output assertions, with no need to render a component, simulate DOM interactions, or mock rendering-related concerns — keeping UI components as "thin" as possible (just wiring logic to rendering) minimizes what actually needs component-rendering-based testing versus what can be tested as plain, fast, isolated unit tests.' },
    { q: 'What makes a codebase "maintainable" and how do you design for it from the start?', a: 'Maintainability comes from clear separation of concerns, consistent conventions/patterns applied uniformly, minimal and well-managed coupling between modules, good test coverage that gives confidence to refactor safely, and documentation of non-obvious decisions — designing for it from the start means establishing these conventions early (even in a small initial codebase) rather than treating them as something to retrofit later once the codebase has already grown large and inconsistent.' },
  ],

  // Code Quality, Testing & Git
  'Testing pyramid: unit, integration, e2e': [
    { q: 'What is the testing pyramid and how do you decide how many tests at each level?', a: 'The testing pyramid recommends having many fast, cheap unit tests at the base, a moderate number of integration tests in the middle, and few, more expensive end-to-end tests at the top — the ratio is driven by cost/speed/confidence trade-offs: unit tests are fast and pinpoint failures precisely but don\'t verify how pieces work together; E2E tests give the highest confidence (testing the real, integrated system) but are slow, flakier, and expensive to maintain, so you use them sparingly for critical user flows.' },
    { q: 'Why is an inverted pyramid (too many E2E tests) a problem?', a: 'E2E tests are slow (each one may take seconds to minutes), flaky (dependent on timing, network, environment state), and expensive to maintain (a small UI change can break many E2E tests) — over-relying on them for coverage that unit/integration tests could provide more cheaply and reliably results in a slow, flaky, high-maintenance test suite that developers start to distrust or skip, undermining the entire purpose of having tests.' },
  ],
  'TDD / BDD and writing meaningful tests': [
    { q: 'What is the Red-Green-Refactor cycle in TDD?', a: 'Red: write a failing test for the behavior you\'re about to implement (it fails since the feature doesn\'t exist yet). Green: write the minimal code needed to make that test pass, without worrying about elegance yet. Refactor: clean up the implementation (and/or the test) now that you have a passing test as a safety net, ensuring the tests still pass after refactoring — this cycle repeats for each new piece of behavior.' },
    { q: 'What makes a test meaningful vs one that only exists for coverage?', a: 'A meaningful test asserts on actual behavior a user or consumer of the code cares about, and would genuinely fail if a real bug were introduced — a test written purely to hit a coverage number (e.g. asserting a function was called without checking it did anything meaningful) provides false confidence, passing regardless of whether the underlying behavior is actually correct.' },
  ],
  'Mocks, stubs, spies, and fakes': [
    { q: 'What is the difference between a mock, a stub, a spy, and a fake?', a: 'A stub returns predetermined, canned responses for specific calls, with no verification of how it was used. A spy wraps a real (or stub) function and records how it was called, letting you assert on call count/arguments afterward. A mock is pre-configured with expectations about how it should be called, and the test itself fails if those expectations aren\'t met. A fake is a lightweight, simplified but genuinely working implementation (like an in-memory database standing in for a real one) rather than just canned responses.' },
    { q: 'When does over-mocking cause tests to pass but bugs to slip to production?', a: 'When a test mocks so much of the actual system under test that it\'s effectively testing the mocks\' behavior rather than the real code\'s behavior — if the mock\'s assumed behavior diverges from the real dependency\'s actual behavior (e.g. the real API changed its response shape but the mock wasn\'t updated to match), the test continues passing against the stale mock while the real integrated system is actually broken, a classic mock/reality drift problem.' },
  ],
  'Component testing (React Testing Library) philosophy': [
    { q: 'What does "test behavior, not implementation" mean in RTL?', a: 'It means writing tests that interact with a component the way a real user would (finding elements by visible text/accessible role, clicking, typing) and asserting on the resulting visible/accessible output, rather than reaching into component internals (state values, instance methods) — this way, refactoring a component\'s internal implementation without changing its user-facing behavior doesn\'t break the test.' },
    { q: 'Why does RTL discourage testing internal state directly?', a: 'Because internal state is an implementation detail that can change freely (renamed, restructured, moved to a different hook) without the component\'s actual user-facing behavior changing at all — a test coupled to specific internal state would break on such a refactor even though nothing observably changed, producing false test failures that discourage safe refactoring rather than genuinely protecting against real regressions.' },
  ],
  'E2E testing (Playwright, Cypress, Detox, Maestro)': [
    { q: 'What are the trade-offs between Playwright and Cypress?', a: 'Playwright supports multiple browser engines (Chromium, Firefox, WebKit) natively, has built-in support for multiple tabs/contexts and better parallelization, and generally has faster execution. Cypress has historically had a more polished interactive debugging experience (time-travel debugging in its UI) and a larger, more mature plugin ecosystem, though it has historically had more limitations around multi-tab/multi-origin testing that Playwright handles more naturally.' },
    { q: 'How do you manage test data and state in E2E tests to prevent flakiness?', a: 'Use dedicated test accounts/database seeding (or API-based setup rather than UI-driven setup) to establish known starting state before each test, clean up/reset state between test runs to avoid tests interfering with each other, avoid relying on shared mutable test data across parallel test runs, and use explicit waits for actual conditions (an element becoming visible) rather than arbitrary fixed sleep delays that are inherently flaky.' },
  ],
  'Visual regression and snapshot testing (pros/cons)': [
    { q: 'What is visual regression testing and what tools support it?', a: 'Visual regression testing captures screenshots of UI components/pages and compares them pixel-by-pixel (or with perceptual diffing) against a baseline, flagging unexpected visual changes — tools like Chromatic (built on Storybook), Percy, and Playwright\'s built-in screenshot comparison support this, catching visual regressions that functional tests (which don\'t check actual rendered appearance) would miss entirely.' },
    { q: 'What is the main problem with snapshot tests that causes them to become maintenance burdens?', a: 'Snapshot tests (especially large, coarse-grained ones like a full component tree serialization) tend to break on any change to the component, whether the change is a genuine regression or an intentional, harmless update — this trains developers to reflexively approve/update snapshots without carefully reviewing the actual diff, defeating the test\'s purpose of catching real regressions and instead becoming a rubber-stamped, low-value maintenance chore.' },
  ],
  'Linting and formatting (ESLint, Prettier, Biome)': [
    { q: 'What is the difference between a linter and a formatter?', a: 'A linter (ESLint) analyzes code for potential bugs, anti-patterns, and style violations, often with configurable rules that can catch genuine logic errors (unused variables, unreachable code, incorrect hook usage). A formatter (Prettier) purely handles code layout/whitespace/style formatting (indentation, quote style, line length) with no concern for logical correctness — the two serve complementary but distinct purposes, one for catching problems, one for consistent visual style.' },
    { q: 'How do you integrate ESLint and Prettier without rule conflicts?', a: 'Use eslint-config-prettier, which disables all of ESLint\'s stylistic/formatting-related rules that could conflict with Prettier\'s own formatting decisions, letting ESLint focus purely on code-quality/correctness rules while Prettier handles all formatting — running them as separate, non-conflicting tools (rather than trying to make ESLint enforce Prettier\'s exact formatting rules, which historically caused friction) is the modern recommended approach.' },
  ],
  'Pre-commit hooks (Husky, lint-staged)': [
    { q: 'How does lint-staged improve on running linting over the entire codebase on each commit?', a: 'lint-staged runs linters/formatters only against the files that are actually staged for the current commit, rather than the entire codebase — this makes pre-commit checks fast (proportional to the size of your actual change, not the whole repo) and avoids surfacing pre-existing lint issues in unrelated files that aren\'t part of the current commit, which would otherwise block commits for problems the developer didn\'t even touch.' },
    { q: 'What are the downsides of slow pre-commit hooks and how do you fix them?', a: 'Slow pre-commit hooks frustrate developers and encourage them to bypass hooks entirely (--no-verify), defeating their purpose — fix this by scoping checks to only staged/changed files (lint-staged), running only fast checks (lint, format) at commit time while deferring slower checks (full test suite, type-check) to a pre-push hook or CI instead, keeping the commit-time feedback loop fast enough that developers don\'t feel motivated to skip it.' },
  ],
  'Git workflows (trunk-based, GitFlow, feature branches)': [
    { q: 'What is trunk-based development and how does it differ from GitFlow?', a: 'Trunk-based development has all developers committing frequently (at least daily) directly to (or via very short-lived branches merged quickly into) a single main/trunk branch, kept always releasable, often behind feature flags for incomplete work. GitFlow uses longer-lived feature/release/hotfix branches with a more elaborate branching model — trunk-based trades some of GitFlow\'s structured branch isolation for much faster integration and fewer, smaller merge conflicts.' },
    { q: 'What practices make trunk-based development safer with a large team?', a: 'Feature flags to hide incomplete work behind a toggle (so unfinished code can be merged to trunk without being user-visible yet), a strong, fast, comprehensive automated test suite gating every merge to trunk, small, frequent commits/PRs rather than large infrequent ones, and a culture of keeping the trunk always in a deployable state, catching problems immediately rather than accumulating them across a long-lived branch.' },
  ],
  'Conventional commits, semantic versioning, and changelogs': [
    { q: 'What is the conventional commits specification and how does it enable automated changelogs?', a: 'Conventional Commits standardizes commit message prefixes (feat:, fix:, chore:, BREAKING CHANGE:) to convey the type and significance of a change in a machine-parseable format — tooling can then automatically generate a changelog by grouping and formatting commits by their type, and automatically determine the correct semantic version bump (major/minor/patch) based on the presence of breaking changes, features, or fixes since the last release, without manual changelog writing.' },
    { q: 'How does semantic versioning (semver) communicate the nature of a change?', a: 'Semver\'s MAJOR.MINOR.PATCH format encodes meaning directly in the version number — a PATCH bump signals a backward-compatible bug fix, a MINOR bump signals new backward-compatible functionality, and a MAJOR bump signals a breaking change requiring consumer code changes — letting downstream consumers make informed decisions about whether/how carefully to upgrade a dependency based purely on the version number itself.' },
  ],
  'Code review culture and effective PRs': [
    { q: 'What makes a code review comment constructive vs demoralizing?', a: 'A constructive comment focuses on the code (not the person), explains the "why" behind a suggestion (not just "change this"), distinguishes between must-fix issues and optional nitpicks/preferences, and is phrased collaboratively ("what do you think about...", "consider...") rather than as a demand or criticism — the goal is improving the code and helping the author grow, not asserting authority or making the author feel judged.' },
    { q: 'How do you keep PRs small and reviewable?', a: 'Break large features into a sequence of smaller, independently-mergeable PRs (e.g. landing the underlying data layer first, then the UI, then the polish), use feature flags to merge incomplete work safely without exposing it to users, and resist the urge to bundle unrelated changes (refactoring alongside feature work) into a single PR, which makes reviews harder to reason about and increases the risk of missing real issues.' },
  ],
  'Managing and paying down technical debt': [
    { q: 'How do you decide when to address technical debt vs ship new features?', a: 'Weigh the ongoing cost of the debt (how much it slows down future work, how often it causes bugs, how much it blocks a specific upcoming feature) against the opportunity cost of delaying feature work — debt that\'s actively compounding (getting worse and more expensive to fix over time) or blocking a near-term priority deserves addressing sooner; debt that\'s stable and low-impact can reasonably be deprioritized in favor of higher-value feature work.' },
    { q: 'How do you make technical debt visible to non-technical stakeholders?', a: 'Translate the debt\'s impact into business terms they care about — "this area causes X% of our production bugs," "this makes feature Y take 3x longer to build than it should," or "this is a risk to our ability to scale for the upcoming launch" — rather than describing it in purely technical terms, framing it as a cost/risk trade-off decision stakeholders can actually weigh against other priorities.' },
  ],

  // Observability, Debugging & Profiling
  'Error tracking (Sentry, Bugsnag) and source maps in production': [
    { q: 'How do source maps enable readable stack traces in production error tracking?', a: 'Production JS is minified/transpiled, so a raw error stack trace points to meaningless minified variable names and collapsed line numbers. Source maps provide a mapping back from the minified production code to the original source file/line/column, letting error tracking tools (Sentry) automatically "de-minify" a stack trace into something matching your actual readable source code, without needing to ship unminified code to production.' },
    { q: 'What information should you attach to a Sentry event to make debugging easier?', a: 'User context (a user/session ID, without PII), the app\'s current state/route at the time of the error, breadcrumbs (a trail of recent user actions/events leading up to the error), relevant tags for filtering (environment, release version, feature flag state), and any relevant custom context specific to the failing operation — the more context attached, the faster you can reproduce and diagnose the root cause without needing to ask the user for more information.' },
  ],
  'Structured logging and log levels': [
    { q: 'What is structured logging and how does it improve log searchability?', a: 'Structured logging emits logs as machine-parseable structured data (JSON with consistent field names) rather than free-form text strings — this lets log aggregation/search tools (Datadog, Elasticsearch) efficiently filter, query, and aggregate logs by specific fields (userId, requestId, errorType) rather than relying on fragile text-pattern matching across unstructured log lines.' },
    { q: 'How do you decide what log level (debug/info/warn/error) to use for an event?', a: 'debug: detailed diagnostic information only useful during active development/troubleshooting, not needed in normal production monitoring. info: normal, expected operational events worth recording for visibility. warn: something unexpected happened but the system recovered/continued functioning. error: something failed and requires attention — choosing the right level ensures alerts/dashboards built on top of these logs surface genuinely actionable signals rather than being drowned in noise.' },
  ],
  'Performance monitoring: RUM and APM': [
    { q: 'What is the difference between Real User Monitoring (RUM) and synthetic monitoring?', a: 'RUM collects actual performance data from real users\' real sessions in production, reflecting genuine diverse device/network/geography conditions. Synthetic monitoring runs automated, scripted checks against your app from controlled environments/locations on a schedule, useful for consistent baseline tracking and catching regressions quickly, but not representative of the full diversity of real-world user experience the way RUM is.' },
    { q: 'How would you set up RUM to track Core Web Vitals for different user segments?', a: 'Use the web-vitals library (or a framework\'s built-in equivalent) to capture each metric in real users\' browsers, and send that data — along with segmentation dimensions (device type, connection type, geography, user cohort) — to an analytics backend, letting you build dashboards that break down performance by segment, revealing whether specific user groups (e.g. slower connections, older devices) are experiencing meaningfully worse performance than the aggregate average suggests.' },
  ],
  'Profiling: Chrome DevTools Performance, Memory, and Coverage tabs': [
    { q: 'How do you use the Performance tab to identify a long task blocking the main thread?', a: 'Record a performance profile while reproducing the slow interaction, then look at the main thread flame chart for any task exceeding roughly 50ms (the threshold above which a task starts to feel like it\'s blocking responsiveness) — clicking into that long task reveals the specific function call stack responsible, letting you pinpoint exactly which code is monopolizing the main thread.' },
    { q: "What does the Memory tab's heap snapshot reveal about a leak?", a: 'A heap snapshot shows every object currently allocated in memory, grouped by constructor/type, with retained size and retaining paths (what\'s holding a reference to each object) — taking snapshots before and after a repeated action that shouldn\'t accumulate memory, then comparing them, reveals which object types are growing unexpectedly and lets you trace the retaining path back to the specific reference that\'s preventing garbage collection.' },
    { q: 'What is the Coverage tab useful for in a production performance audit?', a: 'The Coverage tab shows exactly what percentage of your loaded CSS/JS was actually executed/used during a session, highlighting unused code — this is directly useful for identifying opportunities for code splitting or removing genuinely dead code that\'s being shipped but never actually exercised, reducing wasted bytes in your production bundle.' },
  ],
  'React Profiler and why-did-you-render': [
    { q: 'How do you use the React DevTools Profiler to find which component takes the most time to render?', a: 'Start a recording in the Profiler tab, perform the interaction you want to analyze, then stop recording — the resulting flame graph/ranked chart shows each component\'s render duration per commit, letting you sort/identify which specific components took disproportionately long, with newer versions also showing "why did this render" information indicating what prop/state/context change actually triggered each render.' },
    { q: "What does why-did-you-render detect that React Profiler doesn't?", a: 'why-did-you-render specifically flags avoidable re-renders — cases where a component re-rendered with props/state that are deeply-equal (though not referentially-equal) to the previous render, meaning the re-render was likely unnecessary and could have been prevented with proper memoization — React Profiler shows you timing/what happened, but doesn\'t itself judge whether a given re-render was actually avoidable/wasteful the way why-did-you-render\'s specific heuristic does.' },
  ],
  'Memory-leak detection (detached DOM nodes, listeners, timers)': [
    { q: 'How do you find detached DOM nodes causing a memory leak using Chrome DevTools?', a: 'Take a heap snapshot and search/filter for "Detached" in the constructor filter — detached DOM nodes are elements that have been removed from the visible document tree but are still referenced somewhere in JS memory (preventing their garbage collection); the snapshot\'s retaining path for each detached node shows exactly what JS reference is holding onto it, revealing the specific leak source.' },
    { q: 'What are the most common event listener and timer memory leak patterns in React?', a: 'Adding an event listener (window.addEventListener) or starting a timer (setInterval) inside a useEffect without returning a corresponding cleanup function that removes the listener/clears the timer — this is by far the most common React memory leak pattern, since the listener/timer keeps running (and keeps referencing the component\'s closure, preventing it from being garbage collected) indefinitely after the component has actually unmounted.' },
  ],
  'Feature flags, gradual rollout, and kill switches': [
    { q: 'How do you implement a feature flag system that supports percentage-based rollouts?', a: 'Assign each user a stable, deterministic bucket (often derived by hashing their user ID modulo 100), and configure each feature flag with a rollout percentage — a user sees the feature if their bucket falls within the configured percentage range, ensuring the same user consistently sees the same experience across sessions while letting you gradually increase the percentage as confidence in the feature grows.' },
    { q: 'What is a kill switch and how does it differ from a feature flag?', a: 'A kill switch is a specific type of flag whose sole purpose is emergency disablement — instantly turning off a feature (or an entire non-critical system) in production without a deploy, typically used when something is actively causing harm/errors. Regular feature flags are more general-purpose (gradual rollout, A/B testing, environment-specific behavior) — a kill switch is essentially a feature flag optimized specifically for fast, reliable emergency response.' },
  ],
  'A/B testing and experimentation': [
    { q: 'How do you design an A/B test to avoid bias (e.g. sample ratio mismatch)?', a: 'Ensure truly random, consistent assignment of users to variants (the same user always sees the same variant across sessions), verify the actual observed split between variants matches the intended split (a significant deviation, or "sample ratio mismatch," often indicates a bug in the assignment/tracking logic invalidating the whole experiment), avoid introducing confounding variables (like changing the assignment logic mid-experiment), and ensure sufficient sample size/duration for statistical significance before drawing conclusions.' },
    { q: 'How do you manage feature-flag / experiment variants without polluting your codebase?', a: 'Keep variant-specific logic isolated behind a clear abstraction (a hook like `useExperiment("checkoutFlow")` returning the assigned variant, rather than scattered inline conditionals throughout the codebase), and establish a discipline of removing the flag/experiment code entirely once the experiment concludes and a winner is chosen, rather than letting resolved experiments accumulate as permanent dead conditional branches cluttering the codebase indefinitely.' },
  ],

  // Accessibility
  'WCAG and the POUR principles': [
    { q: 'What does POUR stand for in the context of WCAG, and what does each principle mean?', a: 'Perceivable (information must be presentable to users in ways they can perceive, regardless of sensory ability — alt text, captions, sufficient contrast), Operable (interface components must be usable via various input methods — keyboard-navigable, enough time to complete actions), Understandable (content and operation must be comprehensible — clear language, predictable behavior), and Robust (content must work reliably across a wide variety of user agents and assistive technologies, including future ones).' },
    { q: 'What are the three conformance levels of WCAG (A, AA, AAA)?', a: 'Level A is the minimum, most basic level of accessibility. Level AA is the level most legal accessibility requirements and industry standards target — a reasonable, achievable baseline for most production applications. Level AAA is the strictest level, often difficult or impractical to fully achieve for an entire site, typically pursued only for specific critical content rather than site-wide.' },
  ],
  'Semantic HTML as the foundation': [
    { q: 'Why does using semantic HTML elements provide accessibility for free?', a: 'Semantic elements (`<button>`, `<nav>`, `<header>`, heading levels) carry implicit ARIA roles, keyboard focusability, and expected interaction behavior built directly into the browser — a screen reader announces a `<button>` as an interactive button automatically, and it\'s keyboard-focusable/activatable with no extra code needed, whereas a `<div>` styled to look like a button provides none of this without significant manual ARIA/keyboard-handling work to replicate it.' },
    { q: 'Give examples of replacing non-semantic patterns with semantic HTML.', a: 'A `<div onClick>` styled as a button becomes an actual `<button>`. A series of styled `<div>`s representing a form becomes `<form>`, `<label>`, and proper input elements. A custom-styled "heading-looking" `<div>` becomes an actual `<h2>`/`<h3>` matching its logical position in the document outline. A clickable `<span>` link becomes an actual `<a href>` — in each case, swapping to the semantic equivalent provides built-in accessibility behavior the non-semantic version lacked entirely.' },
  ],
  'ARIA roles, states, and properties (and when not to use ARIA)': [
    { q: 'What is the first rule of ARIA use?', a: 'If a native HTML element or attribute already has the semantics/behavior you need, use it instead of re-purposing another element with ARIA — e.g. use a real `<button>` instead of `<div role="button">`, since native elements provide built-in keyboard behavior and browser/assistive-tech support that manually-added ARIA roles alone don\'t automatically replicate.' },
    { q: 'When should you add aria-live, and what are its values?', a: 'aria-live announces dynamic content changes to screen reader users that occur without a page reload or explicit focus change (a form validation error appearing, a live notification/toast) — use it on the container that will receive the dynamic update. Its values: "polite" (announces once the screen reader finishes its current task, non-interrupting — the common default) and "assertive" (interrupts immediately, reserved for urgent, time-sensitive information).' },
    { q: 'What is the difference between aria-labelledby and aria-describedby?', a: 'aria-labelledby references an element that provides the accessible NAME for the current element (what a screen reader announces to identify what it is) — typically brief. aria-describedby references an element providing additional DESCRIPTION (supplementary detail, read after the name, on request) — typically longer, supplementary context rather than the primary identifying label.' },
  ],
  'Keyboard navigation and visible focus management': [
    { q: 'What makes a custom interactive widget (e.g. a dropdown menu) keyboard accessible?', a: 'It must be reachable via Tab in a logical order, respond to expected keys for its widget type (Enter/Space to activate, arrow keys to navigate options in a menu/listbox, Escape to close), maintain a visible focus indicator at all times, and follow the WAI-ARIA Authoring Practices pattern for that specific widget type, since users relying on keyboard navigation have no other way to operate it without these behaviors correctly implemented.' },
    { q: 'Why is `:focus-visible` preferred over `:focus` for focus styles?', a: '`:focus` applies the focus style for both mouse clicks and keyboard navigation, often producing an unwanted, distracting focus ring on a simple mouse click. `:focus-visible` intelligently applies the style only when the browser determines keyboard (or other non-pointer) navigation was used to reach the element, giving keyboard users the visible focus indicator they genuinely need without adding visual clutter for mouse users who don\'t need it.' },
  ],
  'Focus trapping for modals and dialogs': [
    { q: "How do you trap focus inside a modal so keyboard users can't tab to content behind it?", a: 'Listen for Tab/Shift+Tab keydown events within the modal, and when focus would move past the first or last focusable element inside it, programmatically wrap it back around (moving focus to the last element on Shift+Tab from the first, and to the first on Tab from the last) — often implemented via a "focus trap" utility/library rather than hand-rolled, ensuring keyboard users can\'t accidentally tab out to (invisible, inaccessible) content behind the modal overlay.' },
    { q: 'How do you restore focus when a modal closes?', a: 'Before opening the modal, store a reference to the currently-focused element (document.activeElement) that triggered it, and when the modal closes, call .focus() on that stored reference — this restores the user\'s (especially a keyboard/screen-reader user\'s) position in the page rather than leaving focus lost or reset to the top of the document.' },
  ],
  'Screen readers: VoiceOver, TalkBack, NVDA/JAWS': [
    { q: 'What is the difference between how VoiceOver (iOS/Mac) and TalkBack (Android) interact with your app?', a: 'Both interpret the platform\'s accessibility tree (built from semantic HTML/ARIA on web, or accessibility props on native mobile), but have different gesture conventions for navigation (VoiceOver: swipe left/right to move between elements, double-tap to activate; TalkBack: similar but with some platform-specific differences), and can have subtly different interpretations/support level for certain ARIA attributes, meaning genuinely thorough testing requires checking both, not assuming behavior is identical across platforms.' },
    { q: 'How do you test a component with a screen reader without a physical device?', a: 'Enable VoiceOver on macOS (built-in, Cmd+F5) to test web content, or on iOS Simulator (though full gesture support is more reliable on a real device); enable TalkBack on an Android emulator through its accessibility settings; on desktop web, NVDA (free, Windows) is a commonly used option for broader cross-platform screen reader testing without needing dedicated hardware.' },
  ],
  'Color contrast and not relying on color alone': [
    { q: 'What is the WCAG AA minimum contrast ratio for normal and large text?', a: '4.5:1 for normal-sized text, and a slightly relaxed 3:1 for large text (18pt+ regular, or 14pt+ bold) — large text is more legible at lower contrast, so WCAG allows a lower threshold for it, while normal-sized text requires the stricter 4.5:1 ratio to remain reliably readable.' },
    { q: 'Give an example of using color as the sole means of conveying information (and the fix).', a: 'A form field showing only a red border to indicate an error, with no text/icon explaining what\'s wrong — colorblind users (or anyone in a context where color is hard to perceive) miss the signal entirely. The fix: pair the color indicator with a text error message and/or an icon, so the information is conveyed through multiple channels, not color alone.' },
  ],
  'Accessible forms, labels, and error messaging': [
    { q: "How do you associate a label with a form control, and what happens if you don't?", a: 'Use a `<label for="inputId">` matching the input\'s id (or wrap the input inside the label element) — this creates a programmatic association a screen reader announces when the input receives focus, and also expands the input\'s clickable/tappable target to include the label text. Without this association, a screen reader user has no way to know what a given input field is actually for, since visual proximity alone conveys nothing to non-visual assistive technology.' },
    { q: 'How do you announce form validation errors to screen reader users?', a: 'Associate the error message with its input via aria-describedby (pointing to the error message\'s element id), and mark the input as aria-invalid="true" — for errors appearing dynamically after submission, placing the error text in an aria-live region (or ensuring focus moves to the first error) ensures screen reader users are actually notified of the error rather than it silently appearing with no auditory announcement at all.' },
  ],
  'Automated a11y testing (axe, Lighthouse) and manual audits': [
    { q: 'What percentage of accessibility issues can automated tools like axe catch?', a: 'Roughly 30-40% of accessibility issues are reliably catchable by automated tools — they excel at structural/programmatic issues (missing alt text, insufficient contrast ratios, missing form labels, invalid ARIA usage) but cannot evaluate genuinely subjective or context-dependent aspects (whether alt text is actually meaningful/accurate, whether a keyboard flow is genuinely logical and usable, whether focus order makes sense) that require actual human judgment.' },
    { q: 'What does a manual accessibility audit involve beyond running automated tools?', a: 'Actually navigating the entire app using only a keyboard (no mouse) to verify a logical, complete tab order and that every interactive element is reachable and operable, testing with an actual screen reader to verify announcements make sense and content is understandable non-visually, verifying focus management for dynamic content (modals, route changes), and evaluating whether automated-tool-flagged issues (and issues automated tools can\'t catch at all) genuinely represent good, usable accessibility rather than just technical compliance.' },
  ],

  // Build, Deploy & DevOps
  'Bundlers: Webpack, Vite, Rollup, esbuild, Metro, Turbopack': [
    { q: "How does Vite's native ESM dev server achieve faster HMR than Webpack's bundled approach?", a: 'Vite serves your source files as native ES modules directly to the browser during development, letting the browser itself handle module resolution rather than pre-bundling everything upfront — on a file change, Vite only needs to invalidate and re-transform that single changed module (and notify the browser via HMR), rather than Webpack\'s traditional approach of needing to rebuild a portion of the bundled dependency graph, making Vite\'s HMR near-instant regardless of overall project size.' },
    { q: 'When would you choose Rollup over Webpack for a project?', a: 'Rollup produces smaller, cleaner output with more effective tree-shaking, historically making it the preferred choice for building libraries/packages (where minimal, clean bundle output matters most) rather than full applications — Webpack\'s more elaborate plugin ecosystem and code-splitting/dev-server features are typically more valuable for complex application builds than for a focused library build.' },
  ],
  'CI/CD pipelines (GitHub Actions, GitLab CI, etc.)': [
    { q: 'What are the typical stages in a frontend CI/CD pipeline?', a: 'Install dependencies, lint/type-check, run unit and integration tests, build the production bundle, run E2E tests against the built app (often in a staging environment), and deploy (to staging first, then production, often gated by a manual approval or automated smoke tests) — each stage typically gates the next, failing fast if an earlier, cheaper check fails before running more expensive later stages.' },
    { q: 'How do you speed up CI pipelines with caching (node_modules, build artifacts)?', a: 'Cache node_modules (or the package manager\'s download cache) keyed by the lockfile\'s hash, so dependency installation is skipped/fast when the lockfile hasn\'t changed; cache build tool output (Webpack/Vite\'s build cache, Turborepo/Nx\'s task cache) so unchanged parts of a monorepo don\'t need to be rebuilt from scratch on every CI run — collectively reducing CI run time significantly for incremental changes.' },
  ],
  'Docker basics for frontend build/deploy': [
    { q: 'How do you multi-stage Docker builds to reduce the size of the final image for a Next.js app?', a: 'Use one build stage with full Node.js/build tooling to install dependencies and run the production build, and a separate, minimal final stage (often a slim Node runtime image, or even nginx for a purely static build) that only copies the final build output (not the full node_modules/build toolchain) from the build stage — this keeps the final deployed image significantly smaller than if everything from the build process were included.' },
    { q: 'What goes in a .dockerignore file and why?', a: 'node_modules, .git, local .env files, build output directories, and other files not needed inside the actual Docker build context — excluding them speeds up the build (less data to send to the Docker daemon), reduces the risk of accidentally leaking secrets (local .env files) into the image, and avoids stale local node_modules conflicting with the fresh install performed inside the container.' },
  ],
  'CDN and edge deployment': [
    { q: "What is the benefit of deploying a SPA's static assets to a CDN vs a single origin server?", a: 'A CDN caches and serves assets from geographically distributed edge locations close to each user, reducing latency compared to every user hitting a single, potentially distant origin server, and it also offloads request load from the origin entirely for cached content, improving both performance and scalability/resilience under high traffic.' },
    { q: 'What is the difference between edge compute (CloudFront Functions, Vercel Edge) and a CDN cache?', a: 'A CDN cache just serves pre-existing, cached static content from edge locations. Edge compute lets you run actual, lightweight application logic (redirects, personalization, auth checks) at those same edge locations for every request, even ones that can\'t simply be served from a static cache — essentially bringing a small amount of dynamic server-side execution capability geographically close to the user, rather than only caching already-generated content.' },
  ],
  'Blue-green and canary deployments': [
    { q: 'What is the difference between a blue-green and a canary deployment?', a: 'Blue-green maintains two complete, identical production environments (blue = current live, green = new version) and switches all traffic from blue to green instantly once the new version is verified — an all-or-nothing cutover with instant rollback capability (switching back to blue). Canary gradually shifts a small percentage of traffic to the new version first, monitoring for issues, and progressively increases that percentage — a more gradual, risk-limiting rollout compared to blue-green\'s instant full switch.' },
    { q: 'How do you roll back a bad canary deployment quickly?', a: 'Immediately route 100% of traffic back to the previous stable version (since the canary deployment, by design, only received a small percentage of traffic, most users were never even exposed to the bad version), and halt/reverse the canary\'s traffic percentage increase — the whole point of canary\'s gradual rollout is that a bad deployment is caught and reverted while its blast radius is still small, minimizing the number of affected users.' },
  ],
  'OTA updates (CodePush, EAS Update)': [
    { q: 'What kinds of changes can be shipped via OTA updates, and what requires a store submission?', a: 'OTA updates can ship pure JS/asset changes — bug fixes, new UI logic, updated business logic built from existing native capabilities. Changes requiring a new native binary (and therefore a full store submission/review) include adding a new native module, changing native permissions/entitlements, or upgrading the React Native version itself — OTA can only replace the JS bundle within an already-installed native shell, not the native shell itself.' },
    { q: 'How do you manage version compatibility between OTA updates and native binary versions?', a: 'Tag each OTA update with compatibility metadata (a "runtime version" in EAS Update, or a similar mechanism in CodePush) matching the native binary\'s actual capabilities, so an update is only served to clients running a compatible native binary — preventing a device on an older native binary from receiving a JS update that assumes native APIs it doesn\'t actually have, which would otherwise cause crashes.' },
  ],
  'Rollbacks and release safety': [
    { q: 'What is your strategy for rolling back a frontend release that introduced a critical bug?', a: 'For a web SPA, revert to the previous deployment/build (most modern deploy platforms keep prior builds instantly re-promotable) or use content-hashed assets to quickly re-point the entry HTML at the previous known-good bundle. For a mobile app, use an OTA update to roll back JS-level changes instantly if the bug is JS-only, or trigger an emergency store submission (and communicate to users) if the bug requires a native fix — feature flags are the fastest option of all when the buggy behavior is gated behind one, since disabling the flag requires no deploy at all.' },
    { q: 'How do feature flags enable safer releases and faster rollbacks?', a: 'A new, risky feature shipped behind a flag can be instantly disabled (a config change, not a deploy) the moment a problem is detected, without needing to revert code or wait for a new build/deploy/store-review cycle — this decouples "shipping code" from "activating a feature," letting you ship safely to production ahead of time and control exposure/rollback independently and instantly.' },
  ],
  'Monorepo build orchestration and caching (Nx, Turborepo)': [
    { q: "How does Turborepo's remote cache speed up builds across team members and CI?", a: 'Turborepo can cache the output of each task (build, test, lint) keyed by a hash of its inputs, and share that cache remotely (via Vercel\'s remote cache or a self-hosted equivalent) across all team members\' machines and CI runs — if another developer or a previous CI run already built the exact same code, subsequent builds/tests can be near-instant cache hits, downloading the previous result instead of redoing the work.' },
    { q: 'What is the difference between task pipelines in Turborepo and Nx?', a: 'Both let you define dependency relationships between tasks across packages (e.g. "build" must run for a package\'s dependencies before building that package itself) and cache task outputs based on relevant input hashes — Nx additionally provides a more built-in, opinionated set of generators/plugins for scaffolding and a more integrated dependency-graph visualization tool, while Turborepo tends to be more minimal/configuration-focused, letting teams bring their own tooling choices more freely.' },
  ],

  // State & Data Management
  'Distinguishing server state, client/UI state, form state, and URL state': [
    { q: 'What is server state and why does it need different handling than client UI state?', a: 'Server state is data that actually lives on a remote server and is merely cached/synced on the client (API-fetched data) — it can become stale, needs revalidation/refetching, and is often shared/accessed by multiple parts of the app. Client UI state (a modal\'s open/closed status, a form\'s current input) is genuinely owned by the client with no server source of truth — treating server state like ordinary client state (e.g. hand-managing it with useState) misses the caching, revalidation, and staleness concerns that dedicated server-state libraries (React Query, SWR) are specifically built to handle.' },
    { q: 'What belongs in URL state (query params) vs local component state?', a: 'State that should be shareable via a link, survive a page refresh, or be part of browser back/forward navigation (a search filter, a selected tab, a pagination page number) belongs in URL state (query params) — state that\'s purely transient and specific to the current interaction, with no need to be shareable/bookmarkable (a dropdown\'s temporary open state, an in-progress unsaved form draft) belongs in local component state instead.' },
  ],
  'Choosing Context vs Redux vs Zustand vs Jotai vs Recoil': [
    { q: 'How do you choose between Context, Zustand, and Redux for a given project?', a: 'Context works well for relatively low-frequency-changing, broadly-needed values (theme, current user). Zustand offers a good middle ground — minimal boilerplate, selector-based subscriptions avoiding Context\'s re-render-everything problem, suitable for most app-level shared state needs. Redux (specifically Redux Toolkit) is worth its additional structure/ceremony for very large, complex apps with many interrelated async flows where strict predictability, time-travel debugging, and a mature middleware ecosystem provide real value.' },
    { q: "What makes Jotai's atom-based approach different from a single store?", a: 'Jotai models each independent piece of state as its own small, individually-subscribable "atom," rather than one large combined store object — components subscribe only to the specific atoms they actually use, giving fine-grained re-render control automatically without needing manual selector optimization, which shines for apps with many independent, loosely-related pieces of state.' },
  ],
  'Server-state libraries (React Query, SWR, RTK Query, Apollo)': [
    { q: 'What distinguishes a server-state library from a client state library?', a: 'A server-state library (React Query, SWR) is specifically designed around the unique characteristics of remote data — caching, background revalidation, staleness, deduplication of simultaneous requests, and automatic refetching on window focus/reconnect — concerns that generic client state libraries (Redux, Zustand) don\'t address out of the box, since they were designed for state the client itself owns, not data that\'s merely a cached copy of a remote source of truth.' },
    { q: 'How does RTK Query compare to React Query in terms of integration with Redux?', a: 'RTK Query is built directly into Redux Toolkit, storing its cache within the same Redux store and integrating natively with Redux DevTools — a natural fit if you\'re already using Redux for other client state and want server-state handled through the same ecosystem. React Query is a standalone library with no Redux dependency at all, often chosen specifically to avoid Redux\'s overhead when a project doesn\'t otherwise need it for client state.' },
  ],
  'Immutability and structural sharing': [
    { q: 'What is structural sharing in immutable data updates?', a: 'When you immutably update a nested data structure, structural sharing means only the parts of the structure that actually changed get new object references — unchanged sibling parts of the structure continue to reference the exact same original objects, rather than the entire structure being deep-cloned — this makes immutable updates efficient (avoiding unnecessary full copies) while still preserving reference-equality-based change detection for exactly the parts that did change.' },
    { q: 'How does Immer enable immutable updates with mutable-looking syntax?', a: 'Immer lets you write update logic that looks like direct mutation (`draft.user.name = "New Name"`) against a special "draft" proxy object, and behind the scenes, it records those mutations and produces a genuinely new, immutable state object applying structural sharing automatically — giving you the ergonomic simplicity of mutation-style code while still producing the actual new-reference immutable output React/Redux require for correct change detection.' },
  ],
  'Avoiding over-globalizing state': [
    { q: 'What is the harm of putting all state in a global store?', a: 'Global state that\'s actually only relevant to one component/feature creates unnecessary coupling (other unrelated parts of the app can now read/mutate it), increases the risk of naming collisions and unintended interactions between features, makes the global store harder to reason about as it grows unboundedly, and can cause broader re-renders than necessary if the global state\'s subscription granularity isn\'t carefully managed.' },
    { q: 'How do you identify state that should stay local vs state that truly belongs globally?', a: 'Ask whether more than one, genuinely unrelated part of the component tree actually needs to read or modify this state — if only one component (and its direct children) ever uses it, it should stay local; if it\'s state that represents a cross-cutting application concern (the current authenticated user, app-wide theme, a shopping cart) genuinely needed in many disparate places, it justifies being global.' },
  ],

  // System Design (Frontend)
  'Frontend system design interview approach': [
    { q: 'How do you structure your answer to a frontend system design question?', a: 'Clarify requirements and scope first (functional requirements, scale, target devices/browsers), sketch a high-level component/data architecture, discuss the rendering strategy and state management approach, cover performance/accessibility/API design considerations, and address trade-offs explicitly — structuring the answer top-down (requirements → architecture → details) rather than diving immediately into low-level implementation details demonstrates a mature, systematic approach.' },
    { q: 'What are the key areas to cover when designing a large-scale frontend system?', a: 'Component architecture and reusability strategy, state management (distinguishing server/client/form/URL state), rendering strategy (CSR/SSR/SSG choice per section), performance budget and optimization approach, API design/data fetching patterns, accessibility, testing strategy, and — for genuinely large-scale systems — build/deployment architecture (monorepo vs micro-frontends) and cross-cutting concerns like auth/error handling/logging.' },
  ],
  'Component API and design system architecture': [
    { q: 'How do you design a component API that is flexible but not over-engineered?', a: 'Start with the minimal set of props actually needed for known use cases, favor composition (children, slots) over an ever-growing list of configuration props for variability, and add flexibility incrementally as genuine new requirements emerge rather than speculatively building in configuration options for hypothetical future needs (YAGNI) — a component API should feel natural for its common cases while still being extensible without a rewrite when real new needs arise.' },
    { q: 'What are design tokens and how do they enable consistent theming across a design system?', a: 'Design tokens are named, centralized values (colors, spacing, typography scale, border radii) that both design tools and code reference as the single source of truth, rather than hardcoding raw values throughout components — changing a token\'s value (e.g. the primary brand color) propagates consistently everywhere it\'s referenced, and tokens can be swapped entirely for theming (light/dark mode, white-labeling for different brands) without touching individual component implementations.' },
  ],
  'Rendering strategy selection (CSR vs SSR vs SSG vs ISR)': [
    { q: 'How do you choose a rendering strategy for a marketing page vs a dashboard vs a real-time feed?', a: 'A marketing page (rarely changes, needs strong SEO, benefits from fast static delivery) is a good fit for SSG. A dashboard (highly personalized, per-user data, not indexed by search engines) is typically better as CSR or SSR depending on initial-load performance needs. A real-time feed (constantly updating, highly dynamic) usually needs CSR with client-side polling/WebSocket updates, since neither SSG nor even SSR can meaningfully capture truly real-time data at request time.' },
    { q: 'What are the SEO implications of CSR vs SSR vs SSG?', a: 'CSR ships a mostly-empty initial HTML shell, requiring JS execution before meaningful content exists — search engine crawlers have improved at executing JS, but this remains less reliable/slower for indexing than content that\'s immediately present in the initial HTML. SSR and SSG both deliver fully-rendered HTML immediately (SSR generated per-request, SSG pre-built), giving crawlers immediately-indexable content without any JS execution dependency, generally the safer choice for SEO-critical pages.' },
  ],
  'Designing for i18n and l10n from the start': [
    { q: 'What does internationalizing a React app involve (beyond just translating strings)?', a: 'Beyond string translation: locale-aware date/number/currency formatting (via the Intl API), pluralization rules (which vary significantly across languages, not just singular/plural), text expansion accommodation in layouts (some languages take significantly more space for the same meaning), right-to-left layout support for RTL languages, and locale-aware sorting/collation — treating i18n as purely "swap out strings" misses most of the actual complexity.' },
    { q: 'How do you handle right-to-left (RTL) layouts in a component library?', a: 'Use CSS logical properties (margin-inline-start instead of margin-left, etc.) which automatically flip direction based on the document\'s writing direction, rather than hardcoded physical left/right values that would need manual RTL-specific overrides everywhere — combined with setting the `dir="rtl"` attribute appropriately, this lets a well-built component library adapt to RTL layouts largely automatically rather than requiring a parallel RTL-specific style implementation.' },
  ],
  'Handling large data (virtualization, pagination, streaming)': [
    { q: 'When would you use server-side pagination vs client-side virtualization?', a: 'Use server-side pagination when the full dataset is too large to reasonably fetch/hold in memory at all (millions of records) — only a page\'s worth is fetched at a time. Use client-side virtualization when you\'ve already fetched a reasonably-sized full (or large-page) dataset but rendering all of it as DOM nodes at once would be slow — virtualization only renders the visible subset, while the full dataset is already in memory/state.' },
    { q: 'How does streaming SSR help with pages that have a lot of data to render?', a: 'Instead of the server needing to fully render the entire page (including waiting on all the data-heavy sections) before sending any response, streaming SSR sends fast-to-render parts of the page immediately while slower, data-heavy sections (wrapped in Suspense) stream in progressively as their data resolves — letting users see and interact with the fast parts of the page immediately rather than waiting for the single slowest data-dependent section to determine the entire page\'s load time.' },
  ],
  'Real-time collaboration architecture (overview)': [
    { q: 'How would you design the client architecture for a collaborative text editor like Notion?', a: 'A local, optimistic document model that applies the user\'s own edits instantly, a WebSocket connection streaming other users\' edits in real time, a conflict-resolution mechanism (typically CRDTs or Operational Transforms) to merge concurrent edits from multiple users deterministically and correctly, presence indicators (showing other users\' cursors/selections), and a persistence layer periodically syncing the reconciled document state to a backend/database.' },
    { q: 'What role do CRDTs or Operational Transforms play in real-time collaboration?', a: 'Both solve the core problem of merging concurrent, independent edits from multiple users into a single consistent document without data loss or requiring a central lock. CRDTs achieve this through mathematically conflict-free data structures that merge deterministically regardless of arrival order, with no central coordination needed. Operational Transforms achieve it by transforming each operation against concurrently-applied operations to preserve intent — both are foundational techniques underlying tools like Google Docs and Notion\'s real-time collaborative editing.' },
  ],
  'Cross-cutting concerns: logging, auth, error handling layers': [
    { q: 'How do you centralize error handling in a large React app?', a: 'Use a small number of strategically-placed error boundaries (rather than one per component) to catch and gracefully handle rendering errors at meaningful UI boundaries, a global unhandledrejection/window.onerror listener to catch anything outside React\'s render cycle, and a centralized error-reporting service (Sentry) integration wired into both, so all errors — regardless of source — flow through one consistent reporting/handling pipeline rather than being handled ad-hoc in scattered locations.' },
    { q: 'How do you inject auth headers into all API calls without modifying each call site?', a: 'Build a thin fetch wrapper (or use an HTTP client\'s interceptor system, like axios interceptors) that automatically attaches the current auth token to every outgoing request at one central point, rather than requiring every individual call site throughout the app to remember to add the header manually — centralizing this also makes it trivial to add token-refresh logic in one place rather than duplicating it everywhere.' },
  ],

  // Lead & Engineering Practices
  'Technical trade-off analysis and decision-making': [
    { q: 'Walk me through how you would decide whether to build or buy a particular feature.', a: 'Assess how core/differentiating the feature is to your actual product (core differentiators usually warrant building in-house for full control; commodity functionality like auth or payments often benefits from buying/using an established provider), estimate the total cost of building and maintaining it long-term versus a vendor\'s pricing, evaluate available vendor options against your specific requirements, and weigh the risk/lock-in of depending on a third party against the opportunity cost of engineering time spent building and maintaining it yourself.' },
    { q: 'How do you communicate a technical trade-off to a non-technical stakeholder?', a: 'Translate the trade-off into business terms they actually care about — cost, time-to-market, risk, and user impact — rather than technical jargon; frame it as "option A gets us there faster but with more risk of X, option B is slower but more robust for Y," letting them make an informed decision based on business priorities rather than needing to understand the underlying technical details themselves.' },
  ],
  'Writing RFCs, design docs, and Architecture Decision Records (ADRs)': [
    { q: 'What is the purpose of an RFC or design doc before starting implementation?', a: 'It forces the author to think through the problem, requirements, and approach thoroughly before writing code, surfaces disagreements/blind spots early (when they\'re cheap to address) through team review rather than after significant implementation effort has already been invested, and creates a durable record of the reasoning behind a decision that outlives any single conversation or the original author\'s memory.' },
    { q: 'What should an ADR record, and why does the "why" matter more than the "what"?', a: 'An ADR should record the context/problem, the decision made, the alternatives considered and why they were rejected, and the consequences/trade-offs accepted — the "why" matters more than the "what" because the code itself already shows what was decided; what\'s not recoverable from the code alone is the reasoning, the alternatives that were considered and rejected, and the constraints that were true at the time, which future engineers desperately need when deciding whether that decision still holds or needs revisiting.' },
  ],
  'Estimation and breaking work into deliverable slices': [
    { q: 'How do you break a large feature into incremental deliverables that each provide value?', a: 'Identify a minimal end-to-end "walking skeleton" version of the feature that delivers real (even if limited) value first, then layer additional capability on top in subsequent slices — each slice should be independently shippable/demonstrable and ideally provide some genuine value on its own, rather than slicing purely by technical layer (e.g. "backend first, then frontend") which typically doesn\'t produce anything demonstrable or valuable until the very end.' },
    { q: 'What techniques do you use for more accurate engineering estimation?', a: 'Break work into small enough pieces that uncertainty per piece is manageable, reference historical estimation accuracy for similar past work, explicitly account for unknowns/research spikes as separate estimated items rather than folding uncertainty into a single padded number, and use relative estimation (comparing to previously-completed work) rather than absolute time guesses, which tend to be systematically overconfident for anything involving genuine unknowns.' },
  ],
  'Balancing velocity, quality, and technical debt': [
    { q: "How do you decide when it's acceptable to incur technical debt deliberately?", a: 'Deliberate technical debt is acceptable when there\'s a genuine, time-sensitive reason to move fast (a critical deadline, validating a hypothesis before over-investing) AND there\'s a real plan/commitment to pay it down afterward — the risk is debt incurred "temporarily" that\'s never actually revisited; deliberate debt should be explicitly flagged/tracked (not silently introduced) so the team retains visibility into what shortcuts were taken and why.' },
    { q: 'How do you make technical debt visible and ensure it gets addressed?', a: 'Track debt explicitly (a dedicated backlog/tag, TODO comments linked to tickets, or a regular technical debt review), quantify its impact where possible (bug frequency, development velocity slowdown in the affected area), and advocate for allocating a consistent portion of each sprint/cycle to debt reduction rather than letting it be perpetually deprioritized in favor of always-more-urgent-seeming feature work.' },
  ],
  'Mentoring, pairing, and growing a team': [
    { q: 'How do you approach mentoring a junior engineer who is struggling?', a: 'Understand the specific nature of the struggle first (is it a knowledge gap, a confidence issue, unclear expectations, or something else) rather than assuming, provide concrete, specific feedback tied to actual examples rather than vague generalities, pair-program on genuinely hard problems to model your own thought process, and calibrate the level of support/independence to where they currently are, gradually increasing autonomy as their confidence and skill grow.' },
    { q: 'How do you create an environment where engineers can safely learn from mistakes?', a: 'Respond to mistakes with curiosity ("what happened, what can we learn") rather than blame, model owning up to your own mistakes openly and without defensiveness, treat incidents/bugs as systemic learning opportunities (blameless postmortems) rather than individual failures to punish, and explicitly celebrate/normalize the process of trying, occasionally failing, and learning rather than only rewarding flawless first attempts.' },
  ],
  'Effective code review and feedback culture': [
    { q: 'What are the characteristics of a high-quality code review comment?', a: 'It\'s specific and actionable (not vague), explains the reasoning/why behind the suggestion (not just "change this"), distinguishes clearly between must-fix issues and optional preferences/nitpicks, and is phrased collaboratively and respectfully rather than as a critique of the author — a good comment helps the author understand and grow, not just comply.' },
    { q: 'How do you handle a situation where a reviewer and author disagree on an approach?', a: 'Focus the discussion on the actual trade-offs and reasoning (not on who\'s "right"), consider a quick synchronous conversation if async back-and-forth isn\'t converging, and if it\'s genuinely a matter of preference rather than correctness, generally defer to the author\'s judgment (since they have the most context on the change) — reserving firm pushback for cases with real, concrete downside (correctness, security, maintainability) rather than purely stylistic disagreement.' },
  ],
  'Incident response, on-call, and blameless postmortems': [
    { q: 'What does a blameless postmortem focus on, and why is blame counterproductive?', a: 'A blameless postmortem focuses on the systemic and process factors that allowed an incident to occur and reach production (missing tests, unclear ownership, inadequate monitoring, ambiguous documentation) rather than which individual made the mistake. Blame is counterproductive because it discourages honest, complete incident reporting (people hide or downplay their involvement to avoid punishment), losing exactly the information needed to actually prevent recurrence — a genuinely blameless culture gets more complete, useful information out of every incident.' },
    { q: 'Walk me through how you would handle a production incident from detection to resolution.', a: 'Detect (via alerting/monitoring or a user report), triage severity and assemble the right responders, communicate status to stakeholders/affected users promptly and honestly, mitigate first (stop the bleeding — rollback, feature flag disable, scale up — even before fully understanding root cause), then diagnose the actual root cause once the immediate impact is controlled, and finally conduct a blameless postmortem afterward to extract and act on the lessons learned.' },
  ],
  'Cross-functional collaboration (product, design, backend, QA)': [
    { q: 'How do you handle a situation where design specs conflict with technical constraints?', a: 'Bring the constraint to the design/product conversation early (not after silently implementing a compromised version), explain the actual technical trade-off in terms they can evaluate (cost, timeline, risk), and collaboratively explore alternatives that satisfy the underlying user/business goal within the real constraints, rather than either silently overriding the design or blindly implementing something technically infeasible/risky as specified.' },
    { q: 'How do you build a shared understanding of requirements across engineering, product, and design?', a: 'Involve engineering early in the requirements/design process (not just handed a finished spec), ask clarifying questions to surface ambiguity and edge cases before implementation begins, use shared artifacts (design docs, prototypes, acceptance criteria) that all disciplines can reference and align on, and maintain regular, direct communication throughout the project rather than only at hand-off boundaries.' },
  ],

  // Modern Platform & Trends
  'React Server Components and the server/client boundary': [
    { q: 'What mental model do you use to decide where to place the server/client boundary?', a: 'Keep components server-only by default, and only mark a component (and the boundary at that point) "use client" when it genuinely needs interactivity (hooks, event handlers, browser APIs) — push the client boundary as far down/leaf-ward in the tree as possible, so as much of the tree as possible stays server-only, minimizing the actual client JS bundle.' },
    { q: 'What are the performance benefits of React Server Components for a data-heavy page?', a: 'Server Components can fetch data directly (no client-side waterfall of "render, then fetch, then render again"), their own code/dependencies never ship to the client bundle at all (reducing bundle size for anything server-only, like a heavy markdown parser or database client), and combined with streaming, slow data-heavy sections can be delivered progressively rather than blocking the entire page.' },
  ],
  'Edge computing and edge functions': [
    { q: 'What is the difference between running code at the edge vs in a regional server?', a: 'A regional server runs in one (or a few) fixed geographic data centers, meaning users far from that region experience higher latency. Edge functions run at many geographically distributed points-of-presence close to users worldwide, reducing latency for users regardless of their location — the trade-off is edge runtimes are typically more restricted (no full Node.js APIs) than a full regional server environment.' },
    { q: 'What are the runtime limitations of edge functions (no full Node.js APIs)?', a: 'Edge functions typically run on a lightweight, V8-isolate-based runtime (not full Node.js) — lacking native filesystem access, many Node core modules, and compatibility with npm packages assuming a full Node environment — restricting them to lighter-weight logic (auth checks, redirects, simple personalization) rather than heavy computation or operations requiring full Node.js capabilities.' },
  ],
  'WebAssembly (WASM) use cases': [
    { q: 'What types of tasks benefit from WebAssembly in a web app?', a: 'Computationally intensive tasks where near-native execution speed matters significantly more than typical JS performance — video/image/audio processing, cryptography, physics simulations, running existing C/C++/Rust libraries in the browser (like a full database engine or a codec) — WASM shines specifically for CPU-bound, performance-critical workloads, not for typical UI/DOM-manipulation-heavy application logic, which JS already handles perfectly well.' },
    { q: 'How does WASM integrate with JavaScript in the browser?', a: 'WASM modules run in the same sandboxed environment as JS and can be loaded and instantiated from JS, with functions callable bidirectionally between JS and WASM code — JS handles DOM manipulation, UI, and orchestration, while performance-critical computational work is delegated to the WASM module, combining JS\'s flexibility/DOM access with WASM\'s near-native execution speed for the parts that actually need it.' },
  ],
  'Progressive Web Apps and installable experiences': [
    { q: 'What are the technical requirements for a PWA to be installable on iOS vs Android?', a: 'Both require a valid web app manifest (name, icons, start URL, display mode) served over HTTPS. Android/Chrome additionally requires a registered Service Worker providing basic offline capability to trigger the native "add to home screen" install prompt. iOS/Safari has historically had more limited, less automatic PWA install support (often requiring the user to manually use "Add to Home Screen" from the share menu) and has more restricted background/offline capabilities compared to Android\'s more full-featured PWA support.' },
    { q: 'What capabilities do PWAs still lack compared to native apps?', a: 'Deep OS integration (widgets, some background processing capabilities, certain hardware API access), full parity with native push notification reliability (especially historically limited on iOS), app store discoverability (unless separately distributed through a store wrapper), and generally more restricted background execution — while the gap has narrowed significantly over time, PWAs still can\'t achieve full feature parity with genuinely native apps for every use case.' },
  ],
  'View Transitions API': [
    { q: 'What does the View Transitions API enable and how does it work?', a: 'It lets you create smooth, animated transitions between different DOM states (including across full page navigations for MPAs, or between UI states for SPAs) with minimal code — you wrap a DOM update in `document.startViewTransition(callback)`, and the browser automatically captures before/after snapshots and animates a smooth crossfade/transform between them, without needing to hand-build complex custom transition animation logic.' },
    { q: 'How does it integrate with React Router or Next.js for page transition animations?', a: 'You wrap the navigation-triggering state update (or, for React Router/Next.js, the actual route change) in `document.startViewTransition()`, letting the browser animate the visual transition between the old and new route\'s rendered output — some routing libraries are beginning to add more native/built-in support for this integration, though manual wiring is still common as the API and its framework integrations continue to mature.' },
  ],
  'AI-assisted development and integrating LLMs into apps': [
    { q: 'What are the main patterns for integrating an LLM API into a frontend app?', a: 'Direct client-side calls to the LLM provider (rare, since it exposes API keys — generally avoided), a backend proxy/API route that holds the API key server-side and forwards requests (the standard, secure pattern), streaming responses back to the client via Server-Sent Events or a streaming fetch response for a progressively-appearing "typing" effect, and function-calling/tool-use patterns where the LLM can trigger actual app logic based on its output.' },
    { q: 'How do you handle streaming responses from an LLM in a React UI?', a: 'Read the response body as a stream (via the Fetch API\'s ReadableStream, or a library like the Vercel AI SDK that handles this), appending each incoming chunk of text to a state variable as it arrives, causing the UI to progressively render the response token-by-token as it streams in, rather than waiting for the entire response to complete before showing anything.' },
    { q: 'What are the UX considerations for AI-powered features (latency, error handling, trust)?', a: 'Latency: use streaming to show progressive output rather than a long blank wait, and set expectations with appropriate loading states. Error handling: LLM responses can fail, time out, or produce malformed output — always have a graceful fallback rather than assuming success. Trust: since LLMs can produce plausible-but-wrong ("hallucinated") output, clearly indicate AI-generated content as such, and for high-stakes use cases, provide a way for users to verify or the system to cite sources.' },
  ],
  'Signals and fine-grained reactivity (concept)': [
    { q: 'What is a "signal" in the context of reactivity frameworks?', a: 'A signal is a reactive primitive holding a value that automatically tracks which parts of the UI (or other computations) depend on it, and precisely updates only those specific dependents when the value changes — rather than triggering a broader component re-render and diff process, a signal update directly and surgically updates just the specific DOM node(s) or computation(s) that actually depend on it.' },
    { q: "How does fine-grained reactivity (Solid.js, Angular signals) differ from React's VDOM reconciliation?", a: 'React re-renders an entire component function on a state change and then diffs the resulting virtual DOM tree against the previous one to determine minimal actual DOM updates — the component function itself always re-runs, even if only a tiny piece of its output actually changed. Fine-grained reactivity frameworks skip the component-re-run-and-diff step entirely — a signal update directly, surgically updates just the specific DOM binding that depends on it, without re-executing the surrounding component function or performing any tree diffing at all.' },
  ],
};
